const top_azir = {
  champion: '아지르',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 이동 속도를 높여 빠르게 접근한 뒤 침묵을 걸 수 있으니 거리를 유지하며 (Q)\'사막의 맹습\'으로 견제하세요. 1~2레벨에는 가렌이 (P)\'인내심\'으로 체력을 회복하기 전에 모래 병사로 꾸준히 피해를 입히는 것이 좋아요. 가렌의 접근을 막기 위해 (Q)\'사막의 맹습\'의 둔화 효과를 활용하며 거리를 조절하세요.', lv3: '가렌이 (Q)\'결정타\'를 사용하여 달려들 때 (E)\'신기루\'로 거리를 벌리거나 (Q)\'사막의 맹습\'을 맞춰 둔화시키며 대응하세요. 가렌이 (W)\'용기\'를 켜면 받는 피해가 줄고 보호막이 생기니 무리하게 딜교환하지 말고 (W)\'일어나라!\'로 멀리서 병사만 활용하세요. 가렌의 (E)\'심판\' 범위 안에 들어가지 않도록 모래 병사의 사거리를 적극적으로 활용해야 해요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 체력이 낮은 상태에서 매우 위협적이니 체력 관리에 항상 신경 써야 해요. 가렌이 (Q)\'결정타\'로 빠르게 붙으려고 하면 (R)\'황제의 진영\'으로 가렌의 접근을 차단하며 거리를 유지하세요. 정글러가 근처에 있다면 가렌이 (Q)\'결정타\'로 도망치거나 역습할 수 있으니 라인을 무작정 밀기보다 조심스럽게 운영하세요.', item: '루덴의 메아리를 첫 코어로 선택하여 (Q)\'사막의 맹습\'의 견제력을 높이는 것이 좋아요. 신발은 가렌의 기본 공격 피해를 줄여주는 판금 장화를 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하여 체력이 낮은 상태에서 (R)\'데마시아의 정의\'에 당하지 않도록 마무리하세요.' },
    '갱플랭크': { lv1: '(Q)\'혀어어어업상\'은 대상을 직접 지정해 쏘기 때문에 미니언 뒤에 숨어도 피할 수 없으니 주의하세요. (W)\'일어나라!\'로 병사를 세워 거리 조절을 하며 지속적으로 견제해 주세요. 근접 평타에는 (P)\'불의 심판\' 불이 붙으므로 너무 가까이 붙지 말고 거리만 유지하세요.', lv3: '(E)\'화약통\'이 설치된 주변에서는 싸우지 말고 위치를 파악하며 거리를 벌리세요. (Q)\'사막의 맹습\'으로 상대에게 둔화를 적용해 이동 경로를 제한하며 견제하세요. (W)\'괴혈병 치료\'로 체력을 회복하고 군중 제어를 풀 수 있으니, 이 스킬이 빠진 뒤에 (E)\'신기루\'로 진입해 공격하세요.', lv6: '(R)\'포탄 세례\'가 떨어지는 구역은 둔화가 걸려 위험하니 빠르게 범위를 벗어나세요. (E)\'화약통\' 폭발 범위에 들어가지 않도록 통의 위치를 보며 움직이고, 갱플랭크가 가까이 붙으면 (R)\'황제의 진영\'으로 밀어내어 거리를 확보하세요. 라인을 적당히 당겨 두면 정글러가 왔을 때 (E)\'신기루\'와 (Q)\'사막의 맹습\'으로 추격하기 편해요.', item: '내셔의 이빨을 첫 코어로 선택해 주문력과 공격 속도를 높여 병사들의 공격 횟수를 늘리세요. 신발은 갱플랭크의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'괴혈병 치료\'의 회복량을 줄여야 마무리하기 쉬워요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하니 술통이 떨어지는 위치를 피해 막타를 챙기세요. (Q)\'사막의 맹습\'을 활용해 멀리서 모래 병사로 압박하며 거리를 유지하세요. 그라가스가 (P)\'서비스 시간\'으로 체력을 회복하기 전에 지속적인 피해를 주는 것이 좋아요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 들어오려 하면 (E)\'신기루\'를 사용해 적의 공격을 피하며 대응할 준비를 하세요. (W)\'일어나라!\'를 소환한 뒤 모래 병사로 일직선상의 그라가스를 공격하며 딜교환을 하세요. 그라가스가 (W)\'취중 분노\'를 사용해 받는 피해를 줄이는 동안에는 무리하게 맞서지 마세요.', lv6: '그라가스의 (R)\'술통 폭발\'은 멀리서 던져 밀어내는 스킬이라 막을 수 없으니 적 정글러 쪽으로 밀려나지 않도록 위치를 잡으세요. 그라가스가 (E)\'몸통 박치기\'로 파고들면 (R)\'황제의 진영\'으로 다시 밀어내며 역공하세요. (E)\'신기루\'로 적에게 붙은 뒤 모래 병사로 빠르게 공격하면 킬각을 잡기 쉬워요.', item: '루덴의 메아리를 첫 코어로 올려서 스킬 견제력을 높이세요. 신발은 그라가스의 마법 피해와 (Q)\'술통 굴리기\' 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'으로 인한 회복을 억제하며 킬을 노리기 좋아요.' },
    '그웬': { lv1: '1~2레벨 구간에는 (Q)\'사막의 맹습\'을 사용하여 그웬이 미니언을 먹으러 올 때마다 거리를 두고 피해를 입히세요. 그웬이 평타로 체력을 회복하며 다가오지 못하도록 병사를 활용해 지속적으로 견제해요.', lv3: '(W)\'신성한 안개\'는 대상 지정만 막으니 위치를 정해 보내는 (Q)\'사막의 맹습\'은 안개가 켜져 있어도 그대로 맞아요. 그웬이 (E)\'돌격가위\'로 붙으려 할 때 (Q)\'사막의 맹습\'으로 둔화를 걸어 거리를 벌리고 (W)\'일어나라!\'로 딜교환을 해요.', lv6: '그웬이 (R)\'바느질\'로 둔화를 걸며 접근하면 (R)\'황제의 진영\'을 사용해 거리를 확보하세요. (E)\'신기루\'로 위치를 빠르게 옮겨 (Q)\'싹둑싹둑!\'의 범위를 피하는 것이 중요해요. 정글러가 합류하면 상황에 따라 (R)\'황제의 진영\'을 거리 확보나 아군 쪽 밀어내기 중 하나로만 쓰세요.', item: '첫 코어로 내셔의 이빨을 올려 병사의 공격 속도를 높여 지속적인 피해를 주세요. 신발은 그웬의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 그웬의 (P)\'가위 난도질\' 회복을 줄여서 처치하기 쉽게 만들어요.' },
    '나르': { lv1: '1~2레벨 구간에서는 (Q)\'사막의 맹습\'을 활용해 미니언 사이에서 나르를 견제하며 거리를 유지하세요. 나르의 (Q)\'부메랑 던지기\'가 돌아오는 궤적을 피하면서 (W)\'일어나라!\'로 병사를 소환해 지속적으로 압박하는 것이 좋아요. 나르가 (W)\'슝슝\' 효과로 이동 속도가 빨라져 다가오면 (Q)\'사막의 맹습\'으로 둔화를 걸어 거리를 벌리세요.', lv3: '스킬이 모인 뒤에는 나르가 (E)\'폴짝\'으로 접근하는 타이밍을 조심하며 (E)\'신기루\'로 보호막을 얻고 위치를 잡으세요. 나르의 분노가 차올라 메가 나르로 변신하면 (W)\'쿵쾅\' 기절에 맞지 않도록 거리를 유지하는 것이 중요해요. 나르가 (Q)\'부메랑 던지기\'를 사용하여 둔화를 걸려고 할 때 (Q)\'사막의 맹습\'을 맞춰 대응하세요.', lv6: '메가 나르가 (E)\'우지끈\'으로 뛰어들어 (R)\'나르!\'를 쓰려 하면 (R)\'황제의 진영\'으로 나르를 밀어내며 거리를 확보하세요. (R)\'나르!\'에 던져진 적이 벽에 부딪히면 기절하니 항상 벽에서 떨어진 탁 트인 공간에서 교전하세요. 라인을 밀어 넣은 뒤에는 정글러의 개입에 대비해 (E)\'신기루\'를 아껴두며 시야를 확인하세요.', item: '리치베인을 첫 코어 아이템으로 선택해 스킬을 쓴 뒤 다음 기본 공격에 추가 마법 피해를 넣으세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 정화를 추천해요. 나르의 (W)\'쿵쾅\' 기절이나 (Q)\'부메랑 던지기\' 둔화를 정화로 빠르게 풀 수 있어요.' },
    '나서스': { lv1: '나서스가 (Q)\'흡수의 일격\'으로 미니언 막타를 챙기며 성장하려 하니 거리를 두고 (Q)\'사막의 맹습\'으로 끊임없이 견제하세요. 1~2레벨에는 나서스의 몸싸움이 약하므로 (W)\'일어나라!\'를 섞어주며 미니언과 함께 압박하는 것이 좋아요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 줄어들어 거리를 벌리기 어려워져요. 나서스가 (E)\'영혼의 불길\'로 방어력을 낮추기 전에 (Q)\'사막의 맹습\'으로 멀리서 피해를 입히고 빠지는 리듬을 유지하세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나니 (R)\'황제의 진영\'으로 거리를 벌리며 대응하세요. 라인을 꾸준히 밀어 넣어 나서스의 성장을 늦추면서, 체력이 낮은 상태라면 (E)\'신기루\'를 활용해 킬각을 노려보세요.', item: '지속적인 공격력을 위해 내셔의 이빨을 첫 코어로 선택하세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 라인 관리를 통해 나서스의 성장을 방해하면서 다른 라인에 영향력을 행사하는 것이 중요해요.' },
    '녹턴': { lv1: '1~2레벨에는 (Q)\'사막의 맹습\'을 사용하여 거리를 유지하며 녹턴을 견제해요. 녹턴이 (Q)\'황혼의 인도자\'로 접근하는 것을 방지하기 위해 (W)\'일어나라!\'를 활용해 적절한 간격을 유지하세요. 초반에는 미니언을 안전하게 챙기며 성장에 집중해요.', lv3: '3레벨부터는 (Q)\'사막의 맹습\'으로 압박하며 녹턴의 (W)\'어둠의 장막\' 사용을 유도해요. 녹턴이 (E)\'말할 수 없는 공포\'를 사용하여 연결하려고 하면 (E)\'신기루\'로 빠르게 거리를 벌리며 대응하세요. (W)\'일어나라!\'를 적절히 섞어 딜교환을 진행해요.', lv6: '녹턴이 (R)\'피해망상\'을 켜고 들어올 때는 (R)\'황제의 진영\'을 사용해 녹턴을 밀어내며 거리를 확보하세요. 갑작스러운 진입에 대비해 (E)\'신기루\'를 아껴두고 라인을 당겨 관리하며 정글러의 개입에 대비해요. (E)\'말할 수 없는 공포\'를 맞지 않도록 주의하며 싸워요.', item: '판금 장화와 내셔의 이빨을 가요. 녹턴의 기본 공격 피해를 줄이기 위해 판금 장화를 사고 지속적인 피해를 위해 내셔의 이빨을 선택해요.', spell: '점멸과 정화를 추천해요. 녹턴의 (E)\'말할 수 없는 공포\'로 인한 공포 효과를 정화로 빠르게 풀어낼 수 있어요.' },
    '다리우스': { lv1: '1~2레벨에는 (P)\'과다출혈\' 중첩이 쌓이면 위험하니 절대 다리우스 곁에 붙지 마세요. (W)\'일어나라!\'를 사용해 병사로 지속적으로 견제하며 거리 조절을 하는 것이 중요해요. 다리우스가 무리하게 진입하려 하면 (Q)\'사막의 맹습\'으로 둔화를 걸어 거리 차이를 더 벌리세요.', lv3: '다리우스가 (E)\'포획\'으로 끌어당기려 할 때 거리 조절에 실패했다면 (E)\'신기루\'의 보호막으로 버티며 즉시 빠져나오세요. (W)\'마비의 일격\'에 맞으면 이동 속도가 줄어들어 위험하니 최대한 닿지 않는 거리에서 (W)\'일어나라!\'로 딜교환을 하세요. (E)\'포획\' 스킬이 빠진 것을 확인한 뒤 (Q)\'사막의 맹습\'과 평타 연계로 압박을 가하세요.', lv6: '다리우스가 (R)\'녹서스의 단두대\'를 쓰기 위해 접근하면 (R)\'황제의 진영\'으로 밀어내어 진입을 차단하고 거리 차이를 만드세요. (P)\'과다출혈\' 중첩이 높을 때는 무리하게 딜교환을 하지 말고 라인을 당겨 정글의 도움을 기다리세요. (E)\'포획\'에 끌려가기 전에 (R)\'황제의 진영\'을 적절히 사용해 다리우스의 킬각을 무너뜨리는 것이 핵심이에요.', item: '내셔의 이빨을 가서 주문력과 공격 속도를 챙겨 빠르게 병사 딜을 넣으세요. 신발은 다리우스의 기본 공격 피해를 줄여 주는 판금 장화가 적합해요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 끌어당겼을 때 탈진을 사용해 상대의 피해량과 이동 속도를 줄여 생존 확률을 높이세요.' },
    '라이즈': { lv1: '(W)\'일어나라!\'로 소환한 병사를 활용해 평타 견제를 이어가며 거리를 유지하세요. 라이즈의 (Q)\'과부하\'는 처음 맞은 적에게 들어가니 미니언을 사이에 두고 서면 피해를 줄일 수 있어요. 라이즈의 (Q)\'과부하\' 사거리가 더 기니 사거리 밖에서 견제하려 하지 말고 무리한 맞교환 대신 막타를 챙기세요.', lv3: '라이즈가 (E)\'주문 전이\'를 맞힌 후 (W)\'룬 감옥\'을 사용하면 속박될 수 있으니 주의하세요. 라이즈의 스킬이 빠진 타이밍에 (Q)\'사막의 맹습\'과 (W)\'일어나라!\'를 연계해 딜교환을 시도하세요. 속박되면 (E)\'신기루\' 돌진을 쓸 수 없으니 속박되기 전에 (E)\'신기루\'로 위치를 옮기세요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용하여 도망가거나 아군을 부를 수 있으니 라인 관리에 신경 써야 해요. 라이즈가 붙을 때 (R)\'황제의 진영\'의 병사 벽으로 길을 막아 진입 경로를 끊으세요. 정글러가 근처에 있다면 (E)\'신기루\'로 빠르게 대응하며 압박을 가하세요.', item: '내셔의 이빨을 첫 코어로 올려 병사들의 공격 속도를 높이세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 선택하여 라이즈의 스킬에 대응하세요.', spell: '점멸과 점화를 추천해요. 라이즈가 스킬 연계로 들어올 때 점멸로 대응하며 점화로 마무리 피해를 입히세요.' },
    '럼블': { lv1: '럼블이 (Q)\'화염방사기\'를 켜고 다가오면 뒤로 물러나며 최대한 거리를 유지하세요. (W)\'일어나라!\'를 사용하여 원거리에서 지속적으로 견제하며 첫 웨이브를 받아내세요. (E)\'전기 작살\'에 맞으면 마법 저항력이 줄어 피해가 커지니 무빙으로 피하는 것이 중요해요.', lv3: '럼블이 (W)\'고철 방패\'를 켜면 피해가 흡수되니 방패가 사라질 때까지 공격을 잠시 멈추세요. (Q)\'화염방사기\'를 사용하는 럼블에게 (Q)\'사막의 맹습\'을 사용해 둔화를 걸고 안전한 거리로 물러나세요. 럼블의 열기가 가득 차 과열 상태가 되어 스킬을 못 쓰는 틈에 (W)\'일어나라!\'로 강하게 공격하세요.', lv6: '(R)\'이퀄라이저 미사일\'의 화염 벽 위에서는 피해가 크고 느려지니 즉시 범위를 벗어나세요. 럼블이 무리하게 진입할 때 (R)\'황제의 진영\'으로 밀어내어 흐름을 끊고 (Q)\'사막의 맹습\'으로 이어가면 킬각을 잡을 수 있어요. 럼블의 궁극기는 정글러의 진입과 연계하기 좋으니 라인을 밀 때는 항상 주변을 살피세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 높여 병사 딜교환을 강화하세요. 신발은 럼블의 마법 피해를 줄이고 (E)\'전기 작살\'의 둔화 지속시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 복귀와 합류가 중요하며 점멸로 럼블의 (R)\'이퀄라이저 미사일\' 범위를 빠르게 피하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 입히며 체력을 회복하기 때문에 1~2레벨에는 (Q)\'사막의 맹습\'을 사용해 최대한 멀리서 견제하며 거리를 유지해야 해요. 레넥톤이 분노를 쌓아 (E)\'자르고 토막내기\'로 순식간에 진입하는 것을 경계하며 모래 병사를 활용해 거리를 벌리는 것이 중요해요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 돌진하며 (W)\'무자비한 포식자\' 기절을 맞히려고 할 때 (E)\'신기루\'로 빠르게 위치를 옮겨 대응하세요. 분노가 높은 레넥톤은 기절 지속 시간이 길어지니 (Q)\'사막의 맹습\'의 둔화로 접근을 늦추고 (W)\'무자비한 포식자\'가 빠질 때까지 거리를 유지해야 해요.', lv6: '(R)\'강신\'을 사용한 레넥톤은 추가 체력을 얻고 강력해지니 정면 대결을 피하고 (R)\'황제의 진영\'으로 진입을 막으며 거리를 조절하세요. 레넥톤이 (E)\'자르고 토막내기\'를 사용하여 파고들 때 (R)\'황제의 진영\'을 사용하면 적의 돌진 흐름을 끊고 안전하게 대응할 수 있어요.', item: '첫 코어 아이템으로 내셔의 이빨을 가서 병사들의 공격 속도를 높여주세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤이 (Q)\'양떼 도륙\'을 사용할 때 얻는 체력 회복을 억제하며 교전할 수 있어요.' },
    '렝가': { lv1: '1~2레벨 구간에는 (W)\'일어나라!\'를 활용해 모래 병사로 렝가를 견제하며 수풀 근처로 가지 않도록 주의하세요. 렝가가 (P)\'보이지 않는 포식자\'를 사용하여 수풀에서 갑자기 도약하는 상황을 피하기 위해 적절한 거리를 유지해야 해요.', lv3: '렝가의 (E)\'올가미 투척\'을 피하거나 (E)\'신기루\'로 대응하며 딜교환을 준비하세요. (Q)\'사막의 맹습\'으로 렝가를 둔화시킨 뒤 (W)\'일어나라!\'를 사용하여 거리를 유지하며 지속적으로 피해를 입히는 것이 중요해요.', lv6: '렝가가 (R)\'사냥의 전율\'을 사용하여 위장 상태에서 도약할 때 (R)\'황제의 진영\'을 사용해 적을 밀어내며 대응하세요. 정글러의 개입이 쉬운 구간이므로 수풀 근처에서의 교전을 피하며 라인을 안전하게 관리해야 해요.', item: '판금 장화와 루덴의 메아리를 선택해요. 렝가의 기본 공격 피해를 줄이기 위해 판금 장화를 가고 견제를 위해 루덴의 메아리를 올려요.', spell: '점멸과 탈진을 추천해요. 렝가가 수풀에서 도약해 들어올 때 탈진으로 둔화를 걸고 입히는 피해량을 줄여요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 이용해 빠르게 접근하며 (P)\'룬 검\'으로 강력한 피해를 입히는 구간이 강해요. 1~2레벨에는 (Q)\'사막의 맹습\'을 활용해 최대한 멀리서 견제하며 거리를 유지하세요. 리븐이 붙으려고 하면 (W)\'일어나라!\'를 사용해 병사로 거리를 벌리며 대응해요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 맞으면 순식간에 몰아칠 수 있으니 주의해야 해요. 리븐이 (E)\'용맹\'을 사용해 보호막을 켜고 들어올 때는 (Q)\'사막의 맹습\'으로 맞대응하기보다 거리를 두는 게 좋아요. 리븐의 (W)\'기 폭발\'이 빠진 것을 확인한 뒤 (W)\'일어나라!\'와 병사 공격을 통해 압박을 이어가세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 공격 사거리가 늘어나므로 주의하며 거리 조절을 해야 해요. 리븐이 진입할 때 (R)\'황제의 진영\'을 사용하여 리븐을 뒤로 밀어내며 공격 흐름을 끊으세요. 리븐의 궁극기가 빠진 뒤 (E)\'신기루\'를 사용하여 정글러와 함께 킬각을 노려보세요.', item: '리븐의 기본 공격 피해를 줄여주는 판금 장화를 먼저 구매해요. 첫 코어 아이템으로는 지속적인 공격을 위해 내셔의 이빨을 선택하세요.', spell: '점멸과 탈진을 추천해요. 리븐이 (R)\'추방자의 검\'을 켜고 들어올 때 탈진을 사용해 피해량을 낮추며 대응하세요.' },
    '리산드라': { lv1: '(Q)\'사막의 맹습\'과 (W)\'일어나라!\'로 멀리서 견제하며 거리를 유지하세요. 리산드라의 (Q)\'얼음 파편\'은 미니언을 뚫고 지나가니 미니언 뒤에 너무 붙어있지 마세요. 1~2레벨에는 리산드라가 거리를 좁히기 어려우니 적극적으로 압박하세요.', lv3: '(W)\'서릿발\'은 주변 적을 속박하고 속박 중에는 (E)\'신기루\' 돌진을 쓸 수 없으니 리산드라가 다가오기 전에 미리 거리를 벌리세요. 리산드라가 (E)\'얼음갈퀴 길\'을 사용하여 순간이동해 들어올 때 (Q)\'사막의 맹습\'을 맞춰 거리를 조절하세요. 리산드라의 (Q)\'얼음 파편\'을 피하면서 (W)\'일어나라!\'로 지속적인 피해를 주는 것이 중요해요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용하여 무적 상태가 되면 잠시 딜을 아끼며 기다리세요. 리산드라가 적에게 (R)\'얼음 무덤\'을 쓰면 기절해 스킬을 쓸 수 없으니 시전 사거리 안에서는 거리를 유지하세요. 리산드라의 진입을 예측하여 (E)\'신기루\'로 거리를 조절하며 라인을 관리하세요.', item: '마법 피해가 주력인 리산드라를 상대하기 위해 헤르메스의 발걸음을 먼저 올리세요. 첫 코어 아이템으로는 주문력을 높여주는 루덴의 메아리를 선택해요.', spell: '점멸과 정화를 추천해요. 리산드라의 (R)\'얼음 무덤\' 기절을 정화로 빠르게 풀고 다시 거리를 벌릴 수 있어요.' },
    '마스터이': { lv1: '(W)\'일어나라!\'로 모래 병사를 세워 마스터 이가 가까이 오기 전에 피해를 누적하며 거리를 유지하세요. 1~2레벨에는 마스터 이가 (P)\'2연속 공격\'을 활용해 붙지 못하도록 (Q)\'사막의 맹습\'으로 멀리서 견제하며 체력을 깎아두는 것이 중요해요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용해 진입하면 (Q)\'사막의 맹습\'으로 둔화를 걸어 대응하세요. (E)\'신기루\'의 보호막을 이용해 (E)\'우주류 검술\'의 피해를 견디며 짧게 교환하고, 마스터 이가 (W)\'명상\'을 사용해 체력을 회복하려고 하면 스킬 사용을 잠시 멈추고 기다려주세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하여 진입하더라도 (R)\'황제의 진영\'을 사용해 전투 흐름을 끊으세요. (R)\'최후의 전사\'는 둔화에만 면역일 뿐 밀어내기는 막지 못하니 적절한 타이밍에 궁극기를 써야 해요. 마스터 이가 킬을 먹고 스킬 재사용 대기시간이 줄어들지 않도록 라인 관리에 신경 써주세요.', item: '첫 코어로 내셔의 이빨을 선택해 공격 속도와 주문력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 효과를 점화로 억제하며 싸워야 해요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 적을 밀어내며 둔화를 걸고 평타에 (P)\'마법 흡수\'를 활용해 체력을 회복하며 다가와요. 1~2레벨에는 (Q)\'사막의 맹습\'으로 멀리서 견제하며 마오카이가 붙지 못하도록 거리를 유지하세요. 마오카이가 묘목을 던져 수풀을 감시하기 시작하면 근처에 가지 않도록 조심해요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 돌진하는 동안은 대상으로 지정할 수 없지만 도착하면 속박하니 돌진 경로를 읽고 미리 거리를 벌리세요. 속박되면 (E)\'신기루\' 돌진을 쓸 수 없으니 속박되기 전에 (E)\'신기루\'로 위치를 옮기거나 (W)\'일어나라!\'로 원거리 딜교환을 하세요. 마오카이가 (E)\'묘목 던지기\'를 던진 수풀 근처에서는 싸움을 피하며 파밍에 집중해요.', lv6: '마오카이의 (R)\'대자연의 마수\'는 천천히 전진하며 닿은 적을 속박하니 벽이 다가오면 옆으로 걷거나 (E)\'신기루\'로 경로에서 벗어나세요. 속박되면 (E)\'신기루\'를 쓸 수 없으니 벽이 닿기 전에 미리 움직여야 해요. 라인이 길게 형성되면 마오카이가 (E)\'묘목 던지기\'로 수풀을 감시하니 정글러가 오기 전에 라인을 당겨 관리하세요.', item: '마법 피해가 주력인 마오카이를 상대하므로 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템으로는 공격 속도와 주문력을 모두 챙길 수 있는 내셔의 이빨을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이는 묘목과 벽으로 라인을 길게 가져가니 순간이동으로 복귀하며 성장에 집중하세요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 줄고 군중 제어에 면역이니 (W)\'일어나라!\'로 가볍게 피해를 줘서 태세를 먼저 풀어내세요. (Q)\'공허의 부름\' 투사체가 날아오는 위치를 잘 살펴서 침묵에 걸리지 않게 피하며 거리를 유지해요. 초반 웨이브부터 병사를 소환해 말자하가 편하게 파밍하지 못하게 견제하세요.', lv3: '(E)\'재앙의 환상\'에 걸리면 지속 피해를 입고 (W)\'공허의 무리\' 공허충이 몰려오니 무리하게 교전하지 말고 뒤로 빠지세요. 말자하의 스킬이 빠진 틈을 타 (Q)\'사막의 맹습\'으로 둔화를 걸고 병사 평타로 피해를 입히는 것이 좋아요. (E)\'신기루\'를 사용해 빠르게 거리를 좁히거나 벌리며 말자하의 침묵 사거리를 계속 흔들어 주세요.', lv6: '(R)\'황천의 손아귀\'는 제압 효과라 정화로 풀 수 없으니 제압당하기 전에 거리를 유지하세요. 제압에 걸리면 모든 스킬을 쓸 수 없으니 상대 정글러가 근처에 있는지 시야를 확인하고 신중하게 진입해요. 말자하가 (P)\'공허 태세\'를 잃은 순간에 빠르게 딜교환을 하고 다시 거리를 유지하세요.', item: '내셔의 이빨을 시작 코어로 선택해 병사의 공격 속도와 주문력을 높여 빠르게 견제하세요. 신발은 (Q)\'공허의 부름\'의 침묵 지속 시간을 줄여주는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 순간이동을 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으므로 운영에 도움되는 순간이동을 가져가는 것이 좋아요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 견제하는데, 이 스킬은 대상 지정형이라 미니언 뒤로 숨어도 피할 수 없어요. (W)\'일어나라!\'를 사용하여 모래 병사로 거리를 유지하며 말파이트의 체력을 깎으세요. 초반에는 (Q)\'지진의 파편\' 사거리 안으로 들어가지 않도록 주의하며 (Q)\'사막의 맹습\'으로 멀리서 압박하세요.', lv3: '말파이트가 (W)\'천둥소리\'를 켜고 평타를 치러 다가오면 거리를 벌려야 해요. (E)\'지면 강타\'를 맞으면 공격 속도가 감소하니 (W)\'일어나라!\'로 모래 병사를 소환해 원거리에서 딜교환을 하세요. (Q)\'사막의 맹습\'으로 말파이트에게 둔화를 걸어 접근을 늦추고 붙기 전에 (E)\'신기루\'로 위치를 옮기세요.', lv6: '말파이트의 (R)\'멈출 수 없는 힘\'은 저지 불가 상태로 돌진하여 공중으로 띄우니 정글러가 근처에 있을 때 특히 조심해야 해요. (R)\'황제의 진영\'을 사용하여 말파이트를 밀어내며 거리를 유지하세요. 말파이트가 (R)\'멈출 수 없는 힘\'을 사용한 직후가 공격하기 좋은 시점이니 (E)\'신기루\'로 진입해 피해를 입히세요.', item: '첫 코어 아이템으로 내셔의 이빨을 가서 지속적인 마법 피해를 입히세요. 신발은 (Q)\'지진의 파편\'과 (E)\'지면 강타\'의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 순간이동을 추천해요. (R)\'멈출 수 없는 힘\'의 돌진 경로를 피하기 위해 점멸이 필요하고, 라인 관리를 위해 순간이동을 활용하세요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 범위 스킬이라 미니언 뒤에서도 맞으니 사거리를 확인하며 (Q)\'사막의 맹습\'으로 견제하세요. (P)\'암흑 탄생\' 오라가 켜지기 전에 공격을 세 번 맞지 않도록 주의하며 거리를 유지해야 해요. 1~2레벨에는 (W)\'일어나라!\'로 병사를 소환해 사거리를 활용하며 파밍하세요.', lv3: '모데카이저가 (E)\'죽음의 손아귀\'로 끌어당기려 하면 (W)\'일어나라!\'로 병사를 소환해 사거리를 벌리며 대응하세요. (E)\'죽음의 손아귀\'가 빠진 타이밍에 (Q)\'사막의 맹습\'을 활용해 딜교환을 하고 물러나야 해요. (W)\'불멸\'로 보호막을 생성할 때는 무리하게 싸우지 말고 스킬을 아끼세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 능력치를 뺏기고 순간이동으로도 빠져나갈 수 없으니 주의해야 해요. 모데카이저가 접근하면 (R)\'황제의 진영\'을 사용하여 거리를 밀어내며 대응하세요. 끌려가기 전에 정글러가 합류할 수 있는 위치에서 모데카이저의 스킬이 빠진 뒤 교전을 유도하세요.', item: '대천사의 지팡이를 첫 코어로 올려서 마나와 스킬 가속을 확보하세요. 신발은 모데카이저의 마법 피해를 줄이고 강인함을 얻기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'로 체력을 회복하려는 모데카이저의 회복을 점화로 억제하며 킬각을 잡을 수 있어요.' },
    '문도박사': { lv1: '(Q)\'사막의 맹습\'을 활용해 먼 거리에서 병사로 문도의 체력을 깎으세요. (Q)\'오염된 뼈톱\'은 미니언 뒤에 숨거나 걸어서 피하며 최대한 맞지 않도록 조절해요. 문도가 (P)\'가고 싶은 데로 간다\'로 떨어뜨린 통을 쉽게 줍지 못하게 견제하세요.', lv3: '(W)\'일어나라!\'로 병사를 소환해 지속적으로 거리를 두며 공격하세요. 문도 박사가 (W)\'심장 전기 충격\'을 켜면 피해를 저장해 회복하니 근접 교환을 피해요. (Q)\'오염된 뼈톱\'은 미니언 뒤에 숨거나 움직여서 피하는 것이 안전해요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 회복력이 매우 높아지니 궁극기가 빠진 뒤에 공격하세요. 문도가 다가오면 (R)\'황제의 진영\'으로 접근을 차단하며 병사의 공격을 이어가세요. 정글러와 함께 싸울 때는 문도가 (Q)\'오염된 뼈톱\'을 맞히지 못하도록 거리를 유지해요.', item: '체력이 많은 문도를 상대하기 위해 리안드리의 고통을 첫 코어로 가요. 신발은 마법 관통력을 위해 마법사의 신발을 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 문도 박사의 회복량을 줄여야 킬각을 잡기 편해요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 멀리서 견제하며 (W)\'역병 화살\'의 폭발 피해를 노려요. (Q)\'사막의 맹습\'을 활용해 미니언 사이로 견제하며 적의 접근을 막으세요. 초반에는 무리하게 붙기보다 파밍에 집중하며 적의 화살을 피하세요.', lv3: '바루스가 (W)\'역병 화살\'을 묻힌 뒤 (Q)\'꿰뚫는 화살\'로 터뜨리려 할 때 옆으로 움직여 피하세요. (W)\'일어나라!\'로 병사를 소환해 적절한 거리를 유지하며 (Q)\'사막의 맹습\'으로 압박하세요. (E)\'퍼붓는 화살\'이 깔린 지면은 이동 속도를 늦추니 그 위에서 싸우지 마세요.', lv6: '바루스의 (R)\'부패의 사슬\'에 맞으면 이동이 막혀 (E)\'신기루\'로 도망치기 어려우니 조심해야 해요. (R)\'부패의 사슬\'은 사거리가 길어 정글러와 함께 올 때 위험하니 시야와 거리를 미리 확인하세요. 적의 체력이 낮다면 (E)\'신기루\'로 진입한 뒤 병사들을 활용해 압박하세요.', item: '루덴의 메아리를 첫 코어로 가면 (Q)\'사막의 맹습\'과 함께 강력한 견제가 가능해요. 신발은 마법 관통력을 제공하는 마법사의 신발을 선택하세요.', spell: '점멸과 점화를 추천해요. 점멸로 위치를 조절하고 점화로 적의 체력을 낮게 유지하며 마무리하세요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 최대 체력 비례 피해를 입히니 직접 평타를 주고받는 것은 피하세요. (W)\'일어나라!\'로 모래 병사를 세워 거리 밖에서 지속적으로 견제하며 경험치만 챙겨요. 베인이 (Q)\'구르기\'로 접근하려 하면 뒤로 물러나며 거리를 유지하세요.', lv3: '베인의 (E)\'선고\'에 맞으면 지형에 부딪혀 기절하니 벽에서 멀리 떨어져 싸우세요. (Q)\'사막의 맹습\'으로 둔화를 걸어 베인이 쉽게 접근하지 못하게 하고 (W)\'일어나라!\'로 계속해서 압박해요. (E)\'신기루\'의 보호막을 활용해 베인의 공격을 버티며 적절한 거리에서 딜교환을 하세요.', lv6: '베인이 (R)\'결전의 시간\'을 사용해 (Q)\'구르기\'로 투명해지면 추격이 어려우니 주의하세요. 베인이 가까이 붙으면 (R)\'황제의 진영\'의 병사 벽으로 길을 막아 접근을 끊으세요. (E)\'신기루\'로 먼저 진입했다면 병사들을 활용해 압박하며 체력이 낮을 때 마무리하세요.', item: '내셔의 이빨과 판금 장화를 가세요. 판금 장화는 베인의 기본 공격 피해를 줄여주고 내셔의 이빨은 병사의 공격 속도를 높여 화력을 올려줘요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고, 벽 근처에서 (E)\'선고\'에 맞을 위험이 크면 점멸로 미리 벽에서 벗어나세요.' },
    '볼리베어': { lv1: '(Q)\'사막의 맹습\'으로 멀리서 미니언과 함께 볼리베어를 견제하세요. 볼리베어가 (Q)\'번개 강타\'를 사용해 돌진하며 기절을 시도할 때 거리를 벌려야 해요. 1~2레벨에는 무리하게 붙지 말고 사거리를 유지하며 압박하세요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 표식을 남긴 뒤 다시 사용해 체력을 회복하려 하면 거리를 두세요. (E)\'천공 분열\'이 떨어지는 위치에서는 볼리베어가 보호막을 얻으니 주의하며 (Q)\'사막의 맹습\'으로 둔화를 걸어 대응하세요. 볼리베어의 돌진기가 빠진 틈을 타서 (W)\'일어나라!\'로 지속적인 피해를 입히세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 도약해 포탑을 비활성화하며 들어올 수 있으니 조심하세요. 볼리베어가 접근하면 (R)\'황제의 진영\'을 사용해 밀어내고 거리를 벌려야 해요. 라인을 관리하며 볼리베어가 궁극기로 다이브를 시도하지 못하게 주의하세요.', item: '내셔의 이빨을 첫 코어로 선택하여 병사의 피해를 높이세요. 신발은 볼리베어의 군중 제어 효과를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'를 통해 체력을 회복하는 것을 점화로 억제하세요.' },
    '블라디미르': { lv1: '(W)\'일어나라!\'로 모래 병사를 세우고 지속적으로 공격해 체력을 깎으세요. 블라디미르의 (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으니, (Q)\'수혈\'을 반복해서 사용한 뒤 강화된 타이밍에는 거리를 벌리세요. 초반에는 모래 병사를 이용해 원거리에서 체력을 갉아먹기 편해요.', lv3: '(E)\'선혈의 파도\'는 적 유닛이 가로막을 수 있으니 항상 미니언 뒤에 서서 피해를 줄이세요. (W)\'피의 웅덩이\'로 대상으로 지정할 수 없는 상태가 되어도 웅덩이 위의 둔화와 지속 피해를 받지 않게 벗어나세요. 상대가 웅덩이에서 나온 직후 (E)\'신기루\'로 진입해 빠르게 피해를 주고 빠지세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 동안에는 무리하게 교환하지 말고 뒤로 물러나세요. 블라디미르가 진입할 때 (R)\'황제의 진영\'으로 밀어내어 거리 조절을 하고 아군 정글러의 개입을 유도하세요. (W)\'피의 웅덩이\'가 빠진 상태에서 (Q)\'사막의 맹습\'으로 둔화를 걸고 딜교환을 이어가세요.', item: '모렐로노미콘을 첫 코어로 선택해 (Q)\'수혈\'의 회복량을 깎으세요. 신발은 마법 저항력과 강인함이 있는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 블라디미르의 강력한 (Q)\'수혈\' 회복을 억제해야 킬각을 잡을 수 있어요.' },
    '뽀삐': { lv1: '(W)\'일어나라!\'를 이용해 거리 밖에서 지속적으로 견제하며 뽀삐의 체력을 깎으세요. 뽀삐가 (Q)\'망치 강타\'로 둔화 지대를 만들며 다가오면 그 범위를 피해 뒤로 물러나세요. 방패가 튕겨 돌아오는 타이밍에 맞춰 짧게 공격하고 뽀삐가 보호막을 얻기 전에 빠르게 빠지세요.', lv3: '(E)\'신기루\'를 사용해 진입하거나 도망칠 때 뽀삐가 (W)\'굳건한 태세\'를 켜면 돌진이 막히고 둔화되니 주의하세요. 먼저 (Q)\'사막의 맹습\'으로 뽀삐를 둔화시켜 거리를 벌린 뒤 뽀삐의 (E)\'용감한 돌진\'이 빠진 것을 확인하고 교환하세요. 뽀삐가 벽에 밀어붙이려 하면 라인 중앙에서 싸우는 것이 안전해요.', lv6: '뽀삐가 (E)\'용감한 돌진\'으로 거리를 좁히며 들어올 때 (R)\'황제의 진영\'으로 밀어내어 진입을 차단하세요. 뽀삐가 (R)\'수호자의 심판\'을 충전하며 다가오면 빠르게 범위를 벗어나 정글러가 개입할 시간을 버세요. 라인을 밀어 넣어 포탑 근처에서 (W)\'일어나라!\'로 압박하며 뽀삐가 무리하게 들어오게 유도하세요.', item: '내셔의 이빨을 가서 공격 속도와 주문력을 높여 뽀삐의 높은 체력을 깎으세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 적당해요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 복귀가 중요하며 점멸로 뽀삐의 (E)\'용감한 돌진\' 각을 피하세요.' },
    '사이온': { lv1: '(E)\'학살자의 포효\'는 미니언을 밀쳐내며 관통하므로 미니언 뒤에 숨지 말고 비스듬히 서서 피하세요. (W)\'일어나라!\'로 거리 조절을 하며 사이온이 (Q)\'대량 학살 강타\'를 충전하는 동안 옆으로 움직여 헛치게 만드세요. (Q)\'사막의 맹습\'을 사용해 둔화시키며 안전하게 거리를 유지하세요.', lv3: '(W)\'영혼의 용광로\' 보호막이 켜진 상태에서는 피해가 흡수되니 폭발하기 전까지 (W)\'일어나라!\'로 짧게 견제만 하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하면 (E)\'신기루\'로 빠르게 위치를 옮겨 공격을 피하세요. (E)\'학살자의 포효\'로 방어력이 깎이기 전에 (Q)\'사막의 맹습\'을 적중시켜 사이온의 접근 속도를 늦추세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진해오면 저지 불가라 군중 제어로 막을 수 없으니 돌진 방향에서 미리 벗어나세요. 사이온이 사망해 (P)\'영광스러운 죽음\' 상태가 되면 공격 속도가 매우 빠르니 즉시 거리를 벌려 추가 피해를 입지 마세요. 라인이 너무 밀리면 정글러의 개입을 받기 쉬우니 (Q)\'사막의 맹습\'으로 적절히 라인을 조절하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 사이온에게 지속적인 마법 피해를 입히세요. 신발은 사이온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 강하게 밀기 때문에 순간이동으로 빠르게 복귀하여 경험치 손실을 줄이는 것이 중요해요.' },
    '사일러스': { lv1: '1~2레벨에는 사일러스가 (Q)\'사슬 후려치기\'로 둔화를 걸며 다가오지 못하게 (Q)\'사막의 맹습\'을 활용해 거리를 유지하세요. (P)\'페트리사이트 폭발\'이 충전된 사일러스의 평타는 강력하니 미니언을 먹으러 올 때 (Q)\'사막의 맹습\'으로 미리 둔화를 걸어두세요.', lv3: '3레벨이 되면 사일러스가 (W)\'국왕시해자\'로 들어오며 체력을 회복하려 할 때 (Q)\'사막의 맹습\'과 (W)\'일어나라!\'로 맞받아치세요. (E)\'도주 / 억압\'의 사슬을 피하기 위해 사일러스가 사슬을 던질 때 옆으로 움직이는 것이 중요해요. (E)\'신기루\'로 보호막을 얻으며 사일러스의 진입을 한 번 흘려보내세요.', lv6: '6레벨 이후 사일러스가 (R)\'강탈\'로 (R)\'황제의 진영\'을 가져가면 역으로 밀려날 수 있으니 주의하며 거리를 조절하세요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하며 붙으려 할 때 (R)\'황제의 진영\'을 사용하여 거리를 벌리세요. 사일러스가 궁극기를 훔친 상태라면 정글러의 개입이 무서우니 라인을 당겨서 관리하세요.', item: '첫 코어로 내셔의 이빨을 가서 공격 속도를 확보하세요. 신발은 사일러스의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '세주아니': { lv1: '(Q)\'사막의 맹습\'을 사용하여 멀리서 적의 체력을 깎으며 견제하세요. 세주아니가 (Q)\'혹한의 맹습\'으로 돌진하려고 하면 뒤로 물러나며 거리를 유지해야 해요. 초반에는 무리하게 싸우기보다 미니언을 받아먹으며 성장하는 데 집중하세요.', lv3: '(W)\'일어나라!\'와 (Q)\'사막의 맹습\'을 섞어 쓰며 지속적으로 괴롭혀야 해요. 세주아니의 (W)\'혹한의 서릿발\'을 맞으면 둔화에 걸리니 주의하며 거리 조절을 하세요. 적이 (Q)\'혹한의 맹습\'을 사용했을 때 (E)\'신기루\'를 사용하여 위치를 옮기는 것도 좋은 방법이에요.', lv6: '세주아니의 (R)\'빙하 감옥\'은 챔피언에게만 맞는 올가미라 미니언으로 막을 수 없으니 던지는 방향을 보고 옆으로 피하세요. 세주아니가 (Q)\'혹한의 맹습\'으로 파고들면 (R)\'황제의 진영\'으로 밀어내어 거리를 확보하세요. 적 정글러가 개입할 수 있으니 항상 위치를 조심하고 라인을 적절히 관리해야 해요.', item: '마법사의 신발과 루덴의 메아리를 선택하세요. 마법 관통력을 높여 적에게 더 강한 피해를 입히기 위해서예요.', spell: '점멸과 정화를 추천해요. 세주아니의 (E)\'만년 서리\'나 (R)\'빙하 감옥\' 기절을 정화로 빠르게 풀고 대응할 수 있어요.' },
    '세트': { lv1: '(W)\'일어나라!\'로 모래 병사를 소환해 세트의 체력을 갉아먹으며 거리를 유지하세요. 세트가 (Q)\'주먹다짐\'의 이동 속도 증가를 이용해 빠르게 다가올 때 (Q)\'사막의 맹습\'으로 둔화를 걸어 접근을 늦춰야 해요. 초반에 무리하게 붙지 말고 병사를 통해 계속 견제하며 세트의 체력을 깎아두세요.', lv3: '세트가 (E)\'안면 강타\'로 끌어당겨 기절시키려 할 때 (E)\'신기루\'를 사용하여 빠르게 위치를 옮기며 피하세요. 세트의 투지가 많이 쌓였을 때 날아오는 (W)\'강펀치\'의 중심선에 맞지 않도록 옆으로 이동하는 것이 중요해요. (W)\'강펀치\'가 빗나간 뒤에 (Q)\'사막의 맹습\'과 평타 연계로 짧고 강하게 딜교환을 하세요.', lv6: '세트가 (R)\'대미 장식\'으로 붙잡아 내리꽂으려 할 때 (R)\'황제의 진영\'으로 밀어내어 거리를 벌리고 적의 진입을 차단하세요. (R)\'대미 장식\'에 잡히면 제압 상태가 되어 아무것도 할 수 없으니 세트가 궁극기를 쓰기 전까지는 적당한 거리를 유지하는 것이 좋아요. 라인을 밀어두고 (E)\'신기루\'로 빠르게 빠져나가며 정글러의 개입에 대비하세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 높여 세트의 체력을 빠르게 깎으세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 세트는 (P)\'투기장의 투지\'로 잃은 체력에 비례해 회복하므로 점화의 치유 감소 효과가 효과적이에요.' },
    '쉔': { lv1: '쉔이 (Q)\'황혼 강습\'을 쓰러 다가올 때 (W)\'일어나라!\'로 거리 유지를 하며 계속 공격하세요. 쉔이 스킬을 사용해 (P)\'기 보호막\'을 얻으면 피해가 줄어드니, 보호막이 사라진 뒤에 본격적으로 공격을 퍼부으세요. 쉔이 기의 검을 통해 최대 체력 비례 피해를 입히려는 타이밍을 피해 뒤로 물러나세요.', lv3: '(W)\'의지의 결계\'가 활성화되면 (W)\'일어나라!\'를 통한 공격이 모두 차단되니, 이때는 (Q)\'사막의 맹습\'을 사용해 피해를 입히고 둔화를 거세요. 쉔이 (E)\'그림자 돌진\'으로 진입해 도발하려 하면 (E)\'신기루\'를 써서 빠르게 거리를 벌리거나 쉔의 뒤쪽으로 이동하세요. 도발에 걸리면 스킬을 쓸 수 없으니 쉔의 돌진 경로에서 벗어나는 것이 중요해요.', lv6: '쉔이 (R)\'단결된 의지\'로 다른 라인에 합류하면 빠르게 웨이브를 밀어 포탑을 압박하세요. 쉔이 (E)\'그림자 돌진\'으로 붙었을 때 (R)\'황제의 진영\'으로 밀어내어 진입을 차단하고 거리를 다시 확보하세요. 쉔이 궁극기를 쓰기 전의 짧은 틈을 노려 (Q)\'사막의 맹습\'과 평타를 섞어 킬각을 잡으세요.', item: '내셔의 이빨과 헤르메스의 발걸음을 추천해요. 내셔의 이빨은 공격 속도와 주문력을 높여 쉔의 체력을 깎기 좋고, 헤르메스의 발걸음은 (E)\'그림자 돌진\'의 도발 지속시간을 줄여줘요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 다른 라인에 합류할 때 빠르게 따라가서 대응하기 위해서예요.' },
    '쉬바나': { lv1: '쉬바나가 (Q)\'잉걸불 일격\'을 활용해 근접 교전을 시도할 때를 주의해야 해요. (Q)\'사막의 맹습\'으로 적절한 거리를 유지하며 견제하고 쉬바나의 접근을 막으세요. 초반에는 쉬바나가 (W)\'지옥불 방패\'를 사용하여 달려드는 것을 경계하며 미니언 뒤에서 움직여야 해요.', lv3: '(W)\'일어나라!\'를 사용하여 모래 병사로 지속적인 피해를 입히는 것이 중요해요. 쉬바나가 (E)\'용암 분출\'을 사용하여 둔화를 걸려고 할 때 (E)\'신기루\'를 사용해 위치를 빠르게 변경하세요. 상대의 (W)\'지옥불 방패\' 보호막이 소모된 타이밍에 딜교환을 하는 것이 좋아요.', lv6: '쉬바나가 (R)\'용의 강림\'으로 날아오는 동안은 저지 불가 상태라 막을 수 없으니 착지한 뒤에 (R)\'황제의 진영\'으로 밀어내세요. 변신한 쉬바나는 기본 스킬이 강화되니 무리하게 싸우기보다 (Q)\'사막의 맹습\'으로 둔화를 걸며 거리를 유지하세요. 변신이 끝난 뒤 정글러와 함께 압박하는 것도 좋은 방법이에요.', item: '마법 저항력이 필요하므로 헤르메스의 발걸음을 구매하세요. 첫 코어 아이템은 주문력과 마나를 보충해 주는 루덴의 메아리를 추천해요.', spell: '점멸과 점화를 추천해요. 점화는 쉬바나의 체력 회복 효과를 감소시켜 마무리하는 데 도움을 줘요.' },
    '스웨인': { lv1: '(W)\'일어나라!\'로 모래 병사를 세워 거리에서 계속 견제하세요. 스웨인이 (Q)\'죽음의 손길\'을 쓰며 다가오려 할 때 (Q)\'사막의 맹습\'으로 둔화를 걸어 접근을 늦추는 게 좋아요. (P)\'굶주린 새떼\'로 체력을 회복하기 전에 최대한 피해를 입혀 두세요.', lv3: '(E)\'속박명령\'의 파동이 돌아올 때 속박되지 않도록 옆으로 피하세요. 속박되면 (E)\'신기루\'를 통한 돌진이 불가능하니 파동이 날아오는 타이밍을 잘 살펴야 해요. (W)\'제국의 눈\'의 둔화가 걸리기 전에 (W)\'일어나라!\'로 계속해서 견제하며 상대의 체력을 깎으세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜고 다가오면 (R)\'황제의 진영\'으로 밀어내어 흡수 효과를 끊으세요. (R)\'악의 승천\'의 둔화 효과가 강하므로 무리하게 붙어 싸우지 말고 거리를 유지하며 공격하는 게 좋아요. 정글러가 올 때 (E)\'속박명령\'에 먼저 걸리지 않도록 주의하며 (Q)\'사막의 맹습\'으로 적의 이동 경로를 방해하세요.', item: '내셔의 이빨과 헤르메스의 발걸음을 추천해요. 내셔의 이빨로 공격 속도와 주문력을 높여 빠르게 딜교환하고, 헤르메스의 발걸음의 강인함으로 (E)\'속박명령\'의 속박 시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 스웨인의 (P)\'굶주린 새떼\'와 (R)\'악의 승천\'으로 인한 체력 회복을 점화로 억제해야 킬각을 잡을 수 있어요.' },
    '스카너': { lv1: '(Q)\'사막의 맹습\'을 사용하여 병사로 스카너를 꾸준히 견제하며 적절한 거리를 유지하세요. 스카너가 (Q)\'부서진 대지/지반 돌출\'로 다가오지 못하도록 병사의 공격 범위 안에서 피해를 주는 것이 중요해요.', lv3: '(W)\'일어나라!\'를 사용하여 병사로 지속적인 피해를 누적시키며 압박하세요. 스카너가 (E)\'이쉬탈의 격돌\'로 돌진할 때 (Q)\'사막의 맹습\'을 적절히 사용하여 거리를 조절하는 것이 핵심이에요.', lv6: '스카너가 (E)\'이쉬탈의 격돌\'로 진입할 때 (R)\'황제의 진영\'을 사용하여 경로를 차단하세요. (R)\'꿰뚫기\'에 제압당하면 스킬을 쓸 수 없으니 사거리 안에서는 미리 거리를 벌려 두세요.', item: '헤르메스의 발걸음과 루덴의 메아리를 추천해요. 헤르메스의 발걸음으로 (W)\'대지의 수호자\' 둔화 지속시간을 줄이고 루덴의 메아리로 스킬 피해를 높여요.', spell: '점멸과 탈진을 추천해요. 탈진으로 스카너를 둔화시키고 입히는 피해량을 줄여 진입을 버텨요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 남기며 라인을 빠르게 밀 때 독구름 위에서 교환하지 마세요. (W)\'일어나라!\'로 병사를 세워 안전한 거리에서 견제하며 막타를 챙기세요. 신지드가 (P)\'독성 급류\'로 다가올 때 거리를 유지하며 천천히 뒤로 물러나세요.', lv3: '(W)\'초강력 접착제\' 위에서는 (E)\'신기루\'를 사용할 수 없으니 접착제가 깔린 지역을 빠르게 벗어나세요. (E)\'던져넘기기\'로 던져져 접착제 위에 착지하면 속박되니 주의하며 위치를 잡으세요. 접착제가 빠진 타이밍에 (Q)\'사막의 맹습\'으로 둔화를 걸고 병사로 피해를 누적하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 마시고 달려들면 정글러 유무에 따라 (R)\'황제의 진영\'을 진입 차단이나 아군 쪽 밀어내기 중 하나로만 쓰세요. 궁극기 효과가 끝날 때까지는 무리하게 쫓지 말고 포탑 근처에서 안전하게 파밍하세요.', item: '체력이 많은 신지드를 상대하기 위해 리안드리의 고통을 첫 코어로 선택하세요. 신발은 마법 저항력을 높이고 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'초강력 접착제\'의 둔화와 (E)\'던져넘기기\' 이후의 속박을 빠르게 풀고 도망칠 수 있어요.' },
    '신짜오': { lv1: '(Q)\'사막의 맹습\'을 사용하여 거리를 유지하며 신 짜오의 체력을 깎으세요. 신 짜오가 (W)\'풍전참뢰\'로 둔화를 걸고 다가올 때는 (W)\'일어나라!\'로 병사를 소환해 거리를 조절해야 해요. 초반에는 무리한 공격보다 미니언을 먼저 챙기며 안정적으로 성장하는 것이 중요해요.', lv3: '신 짜오가 (E)\'무쌍돌격\'을 사용하여 돌진하면 (E)\'신기루\'를 통해 위치를 옮기며 대응하세요. (Q)\'삼조격\'의 세 번째 공격인 공중으로 띄우는 효과를 맞지 않도록 (Q)\'사막의 맹습\'으로 둔화를 걸어주세요. 신 짜오가 (W)\'풍전참뢰\'를 먼저 사용하도록 유도하면 딜교환에서 이득을 볼 수 있어요.', lv6: '신 짜오가 (R)\'현월수호\'를 쓰면 창이 닿는 거리 밖에 있는 적의 공격에 피해를 입지 않으니 그동안은 공격을 멈추고 거리를 벌리세요. 신 짜오가 (E)\'무쌍돌격\'으로 들어올 때 (R)\'황제의 진영\'으로 밀어내어 진입을 막으세요. 라인을 빠르게 밀어넣고 정글러의 위치를 확인하며 위험한 곳에는 가지 마세요.', item: '판금 장화와 루덴의 메아리를 구매하세요. 판금 장화는 신 짜오의 기본 공격 피해를 줄이고 루덴의 메아리는 스킬 피해를 높여줘요.', spell: '점멸과 탈진을 추천해요. 신 짜오가 (E)\'무쌍돌격\'으로 붙었을 때 탈진으로 입히는 피해량을 줄여 생존력을 높여요.' },
    '아이번': { lv1: '(Q)\'사막의 맹습\'을 활용해 아이번이 다가오지 못하도록 멀리서 꾸준히 견제하세요. 아이번이 (Q)\'덩굴뿌리\'를 사용해 돌진할 수 있는 거리를 주지 않는 것이 중요해요. 첫 웨이브를 안정적으로 받아내며 사거리를 유지하세요.', lv3: '(W)\'일어나라!\'로 병사를 소환해 (Q)\'사막의 맹습\'의 사거리를 확보하세요. 아이번의 (Q)\'덩굴뿌리\'를 맞지 않도록 움직임에 신경 써야 해요. (Q)\'덩굴뿌리\'에 속박되면 (E)\'신기루\' 같은 돌진을 쓸 수 없으니 속박되기 전에 움직임으로 피하세요.', lv6: '(R)\'데이지!\'가 소환되면 소환수의 공격과 아이번의 협공을 조심하세요. 아이번이 근접했을 때 (R)\'황제의 진영\'을 사용해 적을 밀어내며 거리를 확보하세요. 라인을 적절히 밀어넣어 상대 정글러의 개입을 까다롭게 만드세요.', item: '헤르메스의 발걸음과 루덴의 메아리를 추천해요. 헤르메스의 발걸음으로 아이번의 마법 피해와 (Q)\'덩굴뿌리\' 속박 시간을 줄이세요. 루덴의 메아리를 통해 강력한 마법 피해를 입히며 라인전을 진행하세요.', spell: '점멸과 정화를 추천해요. 아이번의 (Q)\'덩굴뿌리\'에 속박되었을 때 정화로 빠르게 벗어날 수 있어요. 점멸을 사용하여 아이번의 스킬을 피하거나 위치를 잡으세요.' },
    '아칼리': { lv1: '(Q)\'사막의 맹습\'으로 아칼리를 견제하며 거리를 유지하세요. 아칼리가 (Q)\'오연투척검\'을 던지며 둔화를 걸려고 하면 뒤로 물러나며 피해를 최소화해야 해요. (W)\'일어나라!\'로 병사를 소환해 아칼리가 근접하지 못하도록 압박하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 돌진해 올 때 (E)\'신기루\'로 거리를 벌리며 대응하세요. 아칼리가 (W)\'황혼의 장막\' 안에 들어가면 대상으로 지정할 수 없어 병사 공격이 닿지 않지만, 위치를 정해 보내는 (Q)\'사막의 맹습\'은 연막 위치를 겨냥해 쓸 수 있어요. (Q)\'사막의 맹습\'을 아칼리의 돌진 경로에 미리 써서 둔화를 거는 것이 좋아요.', lv6: '아칼리가 (R)\'무결처형\'으로 들어올 때 (R)\'황제의 진영\'을 사용해 밀어내며 거리를 확보하세요. 아칼리가 (W)\'황혼의 장막\'을 쓰고 접근하면 무리하게 싸우지 말고 라인을 밀어넣고 포탑 근처에서 대기하세요. 체력이 낮을 때는 아칼리의 돌진 연계에 주의하며 생존에 집중해야 해요.', item: '헤르메스의 발걸음과 대천사의 지팡이를 선택하세요. 헤르메스의 발걸음으로 마법 저항력을 얻고 대천사의 지팡이로 주문력을 높이며 마나를 확보하세요.', spell: '점멸과 탈진을 추천해요. 탈진을 사용해 아칼리의 진입 시 입히는 피해량을 줄여 생존력을 높여요.' },
    '아크샨': { lv1: '(W)\'일어나라!\'를 사용해 병사로 거리를 유지하며 견제하세요. (Q)\'복수의 부메랑\'의 궤적을 파악하며 최대한 덜 맞으면서 시작 웨이브를 받아내야 해요. 무리하게 딜교환을 하기보다 경험치 획득에 집중하세요.', lv3: '(E)\'영웅의 비상\'으로 진입하는 타이밍에 맞춰 (Q)\'사막의 맹습\'을 사용하여 이동 속도를 늦추세요. 상대가 갈고리로 들어올 때 (E)\'신기루\'의 보호막을 활용해 피해를 흡수하며 빠르게 거리를 벌리세요. (Q)\'복수의 부메랑\'이 돌아올 때 위치를 옮겨 피해를 최소화해야 해요.', lv6: '(E)\'영웅의 비상\'으로 들어오는 적을 (R)\'황제의 진영\'으로 밀어내어 진입을 차단하거나 아군 쪽으로 밀어내어 킬각을 잡으세요. 체력이 낮아지면 (R)\'인과응보\'의 강력한 마무리 피해를 입을 수 있으니 주의하며 라인을 유지하세요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 내셔의 이빨은 공격 속도와 주문력을 높여줘요.', spell: '점멸과 순간이동을 추천해요. 빠른 합류와 생존을 위해 필수적인 주문이에요.' },
    '아트록스': { lv1: '아트록스가 (Q)\'다르킨의 검\'을 사용하여 거리를 좁히며 공격할 수 있으니 (Q)\'사막의 맹습\'으로 멀리서 먼저 견제하세요. 1~2레벨에는 무리하게 붙기보다 병사를 소환해 거리를 유지하며 파밍에 집중해요. 아트록스가 (P)\'사신 태세\'를 활용해 체력을 회복하지 못하도록 거리 조절을 철저히 하세요.', lv3: '아트록스가 (W)\'지옥사슬\'을 사용하면 범위 안에서 즉시 벗어나 중앙으로 끌려가지 않도록 주의하세요. (W)\'일어나라!\'로 소환한 병사를 활용해 (Q)\'다르킨의 검\'의 끝자락 공격을 피하며 일방적인 딜교환을 시도해요. 아트록스의 (E)\'파멸의 돌진\'이 빠진 타이밍에 (Q)\'사막의 맹습\'으로 압박하면 좋아요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하면 공격력과 체력 회복량이 크게 늘어나니 정면 승부는 피하세요. 아트록스가 (E)\'파멸의 돌진\'으로 파고들 때 (R)\'황제의 진영\'을 사용하여 적의 진입을 끊으세요. 라인을 당겨두고 정글러의 개입을 유도하며 (E)\'신기루\'로 생존할 준비를 하세요.', item: '루덴의 메아리를 첫 코어로 선택해 마나와 주문력을 확보하고 견제력을 높이세요. 신발은 아트록스의 기본 공격 피해를 줄이기 위해 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 아트록스는 (P)\'사신 태세\'와 (E)\'파멸의 돌진\'으로 회복이 많으니 점화로 회복을 억제하는 것이 좋아요.' },
    '암베사': { lv1: '(W)\'일어나라!\'로 거리 유지하며 견제하세요. (Q)\'교활한 휩쓸기\'의 바깥 날 범위에 맞지 않게 주의하고, 암베사가 (P)\'용사냥개의 발걸음\'으로 빠르게 접근하면 뒤로 물러나세요. 초반에는 최대한 평타 견제로 체력을 깎는 게 중요해요.', lv3: '(W)\'배척\'의 보호막 준비 시간에는 공격을 멈춰 피해량 증가를 막으세요. (E)\'찢어 가르기\'로 둔화가 걸리면 (Q)\'사막의 맹습\'을 사용해 거리 조절을 하고, 암베사가 파고들면 (E)\'신기루\'로 빠르게 빠져나와야 해요. 암베사의 돌진 쿨타임 동안 (W)\'일어나라!\'로 일방적인 딜교환을 하세요.', lv6: '(R)\'공개 처형\'은 가장 멀리 있는 챔피언을 제압하니, 거리 조절에 유의하고 제압 중에는 어떤 스킬도 쓸 수 없어요. 암베사가 진입하면 (R)\'황제의 진영\'으로 밀어내어 거리를 벌리고 다시 (W)\'일어나라!\'로 공격하세요. 정글 개입 시에는 (E)\'신기루\'를 아껴두어 (R)\'공개 처형\' 이후의 추격을 피하세요.', item: '내셔의 이빨과 판금 장화를 추천해요. 내셔의 이빨로 지속 딜을 높이고, 판금 장화로 암베사의 기본 공격 피해를 줄여야 해요.', spell: '점멸과 점화를 추천해요. 점화로 암베사의 체력 회복을 억제하고 킬각을 잡는 게 좋아요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 견제하며 기절을 노려요. (Q)\'냉기 폭발\'의 투사체가 날아올 때 옆으로 움직여 피한 뒤 (Q)\'사막의 맹습\'으로 병사를 보내 견제하세요. 초반에는 거리를 유지하며 상대의 스킬이 빠지기를 기다리는 게 좋아요.', lv3: '애니비아가 (Q)\'냉기 폭발\'로 냉각을 걸면 (E)\'동상\'의 피해가 크게 늘어나니 조심해야 해요. 상대의 (Q)\'냉기 폭발\'이 빗나갔을 때 (W)\'일어나라!\'로 병사를 소환해 딜교환을 시도하세요. (W)\'결정화\'로 길을 막을 수 있으니 벽이 생기면 무리하게 진입하지 마세요.', lv6: '애니비아가 (R)\'얼음 폭풍\'을 사용하면 범위 내에서 이동 속도가 느려지니 주의하세요. 애니비아를 처치하더라도 (P)\'환생\'으로 알이 되어 살아날 수 있으니 알을 끝까지 확인해야 해요. (R)\'황제의 진영\'을 사용해 애니비아를 밀어내며 거리를 조절하거나 정글러와 함께 압박하세요.', item: '내셔의 이빨을 첫 코어로 올려서 공격 속도와 주문력을 챙기세요. 신발은 애니비아의 마법 피해와 군중 제어에 대비해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'로 인한 기절을 정화로 빠르게 풀 수 있어요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'을 내질러 회오리바람 중첩을 쌓지 못하게 거리를 두세요. (W)\'일어나라!\'를 소환해 야스오의 (P)\'낭인의 길\' 보호막을 먼저 걷어내며 견제하세요. 야스오가 다가오려 하면 (Q)\'사막의 맹습\'으로 둔화를 걸어 거리를 유지하세요.', lv3: '(W)\'바람 장막\'은 투사체만 막으니 장막이 켜진 동안은 딜교환을 서두르지 말고 사라질 때까지 거리를 유지하세요. 야스오가 (E)\'질풍검\'으로 진입할 때 (E)\'신기루\'로 빠르게 거리를 벌리거나 보호막을 얻어 피해를 줄이세요. (Q)\'강철 폭풍\'의 회오리바람이 빠진 뒤에 (W)\'일어나라!\'와 병사 공격으로 강하게 압박하세요.', lv6: '야스오의 (Q)\'강철 폭풍\' 회오리에 띄워지면 바로 (R)\'최후의 숨결\'로 이어지니 주의하세요. 야스오가 (E)\'질풍검\'으로 거리를 좁히며 들어올 때 (R)\'황제의 진영\'으로 밀어내어 진입을 차단하세요. 라인을 당겨 정글러의 도움을 기다리세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 확보하세요. 신발은 야스오의 평타와 치명타 피해를 줄여주는 판금 장화가 적당해요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 복귀와 합류가 중요하며 점멸로 야스오의 (Q)\'강철 폭풍\' 회오리를 피할 수 있어요.' },
    '오공': { lv1: '1~2레벨에는 오공이 (Q)\'파쇄격\'을 사용하여 사거리가 늘어난 평타와 방어력 감소 효과를 활용하려 할 거예요. (Q)\'사막의 맹습\'을 활용해 멀리서 적을 견제하며 거리 조절에 신경 쓰세요. 오공이 근접하지 못하도록 병사를 소환하여 대응하세요.', lv3: '오공이 (E)\'근두운 급습\'으로 돌진하며 분신을 만들 때 (E)\'신기루\'를 사용하여 적의 진입을 방해하거나 위치를 옮기세요. 오공이 (W)\'분신 전사\'로 투명해지면 분신이 남으니 분신과 본체를 구분하며 무리하게 스킬을 쓰지 마세요. 오공의 (E)\'근두운 급습\'을 먼저 피한 뒤 (Q)\'사막의 맹습\'과 (W)\'일어나라!\'로 딜교환을 하세요.', lv6: '오공이 (R)\'회전격\'을 사용하여 공중에 띄우려 할 때 (R)\'황제의 진영\'을 사용해 진입을 차단하세요. (R)\'회전격\'을 맞고 공중에 뜨면 스킬을 쓸 수 없으니 주의가 필요해요. 오공의 진입을 (R)\'황제의 진영\'으로 막아낸 뒤 병사들을 배치해 라인 관리를 하며 정글러의 위치를 확인하세요.', item: '첫 코어 아이템으로 루덴의 메아리를 가서 견제력을 높이세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 오공이 (E)\'근두운 급습\'으로 들어올 때 탈진을 사용해 들어오는 피해량을 줄이세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 사용해 원거리에서 지속적으로 견제하며 (P)\'영혼 방호술\'로 체력을 회복해요. (Q)\'사막의 맹습\'을 활용해 거리를 유지하며 병사를 이용해 파밍을 방해하고 견제하세요. 오로라의 (Q)\'이중 저주\'가 되돌아오는 경로를 예측해 옆으로 움직이는 것이 중요해요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하면 억지로 쫓아가지 말고 (W)\'일어나라!\'로 병사를 배치해 거리를 유지하세요. 오로라가 (W)\'장막 너머로\'로 투명해지면 (Q)\'사막의 맹습\'을 아끼며 재등장을 기다리는 것이 좋아요. 오로라가 (Q)\'이중 저주\'를 재사용하기 전에 (E)\'신기루\'를 사용하여 대응하세요.', lv6: '오로라가 (R)\'세계의 경계\'로 만든 영역 안에서는 (R)\'황제의 진영\'을 사용해 적을 밀어내며 거리를 조절하세요. 오로라의 (W)\'장막 너머로\'를 경계하며 정글러의 개입을 대비하고 미니언 뒤에서 대기해야 해요. 오로라가 영역을 넘나들 때 (E)\'신기루\'로 빠르게 위치를 옮기며 (Q)\'사막의 맹습\'으로 킬각을 노려보세요.', item: '첫 코어 아이템은 내셔의 이빨을 선택하고 신발은 헤르메스의 발걸음을 가세요. 내셔의 이빨은 병사 공격에 필요한 공격 속도와 주문력을 주고, 헤르메스의 발걸음은 오로라의 마법 피해와 (E)\'마법의 문\' 둔화 시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 오로라는 (P)\'영혼 방호술\'로 체력을 회복하니 점화로 회복 효과를 줄여주세요.' },
    '오른': { lv1: '(W)\'일어나라!\'로 모래 병사를 세워 거리에서 계속 견제하세요. (Q)\'용암 균열\'은 지면에 균열이 생긴 뒤 기둥이 솟으니 표시를 보고 빠르게 피하세요. 1~2레벨에는 오른의 체력이 높으니 무리하지 말고 막타를 챙기며 딜교환을 하세요.', lv3: '(E)\'화염 돌진\'이 벽에 부딪히면 공중으로 띄우니 벽 근처에 서지 말고 (E)\'신기루\'로 빠르게 거리를 벌리세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되어 이동 불가 지속시간이 늘어나니 전진하는 방향을 피하세요. 오른의 돌진기가 빠진 뒤에 (Q)\'사막의 맹습\'으로 둔화를 걸며 일방적인 공격을 하세요.', lv6: '(R)\'대장장이 신의 부름\' 정령이 다가오면 옆으로 피하고, 오른이 돌진해 박치기하려는 순간 (R)\'황제의 진영\'으로 밀어내어 공중으로 띄우는 것을 막으세요. 오른은 (P)\'간이 대장간\'으로 라인에서 바로 아이템을 만들 수 있어 오래 버티니 라인을 무리하게 밀다 정글 개입에 노출되지 않게 주의하세요. 띄워진 상태에서는 스킬을 못 쓰니 정령의 경로에서 벗어나는 것에 집중하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 오른에게 지속 피해를 입히세요. 신발은 마법 관통력을 높여주는 마법사의 신발이 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 튼튼해서 한 번에 처치하기 어려우니 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력과 이동 속도를 낮추며 달려들 수 있으니 거리를 잘 유지하세요. (Q)\'사막의 맹습\'으로 멀리서 병사를 보내 견제하며 올라프의 도끼를 피하는 것이 중요해요. 올라프가 도끼를 주우러 가는 동안에는 (Q)\'사막의 맹습\'으로 견제하세요.', lv3: '올라프가 (W)\'버티기\'를 사용하여 보호막을 얻는 동안에는 무리한 딜교환을 피하고 거리를 두세요. 올라프가 (E)\'무모한 강타\'로 들어올 때 (E)\'신기루\'로 위치를 빠르게 옮기며 대응하는 것이 좋아요. (Q)\'사막의 맹습\'으로 둔화를 걸어 올라프가 도끼를 주우러 가기 어렵게 만드세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되니 정면 승부는 피해야 해요. (R)\'라그나로크\' 전에 (R)\'황제의 진영\'을 미리 써서 거리를 확보하고 그동안에는 밀어내기를 노리지 마세요. 올라프의 체력이 낮아져 (P)\'광전사의 분노\'로 흡혈이 강해지는 타이밍을 조심하며 대응하세요.', item: '영겁의 지팡이를 첫 코어 아이템으로 선택해 체력과 마나를 확보하세요. 신발은 올라프의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 올라프의 (P)\'광전사의 분노\'로 인한 체력 회복을 억제하며 싸우세요.' },
    '요네': { lv1: '(W)\'일어나라!\'를 사용하여 원거리에서 계속 견제하며 체력을 깎으세요. 요네가 (Q)\'필멸의 검\'을 두 번 맞히면 돌진하며 띄우니, 첫 중첩이 쌓였다면 거리를 더 벌리세요.', lv3: '요네가 (E)\'영혼해방\'을 쓰고 진입하면 (Q)\'사막의 맹습\'으로 둔화를 걸어 접근을 늦추세요. (W)\'영혼 가르기\'로 보호막을 얻기 전까지 (W)\'일어나라!\'로 짧게 딜교환을 하세요. 돌풍에 띄워질 것 같으면 (E)\'신기루\'로 빠르게 위치를 옮겨 피하세요.', lv6: '요네가 (R)\'운명봉인\'으로 진입할 때 (R)\'황제의 진영\'으로 밀어내어 연계를 끊으세요. (E)\'영혼해방\' 중인 요네는 이동 속도가 빠르니 무리하게 쫓지 말고 육신으로 돌아올 때까지 기다리세요. 요네의 궁극기 사거리가 길어 정글 개입이 위험하니 라인을 당겨서 플레이하세요.', item: '내셔의 이빨과 판금 장화를 추천해요. 내셔의 이빨로 공격 속도와 주문력을 높여 지속 딜을 넣고, 판금 장화로 요네의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 빠르게 복귀하여 라인 손실을 줄이는 것이 중요해요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 미니언을 처치해 무덤을 만드는 것을 막기 위해 (Q)\'사막의 맹습\'으로 계속 견제하세요. (W)\'일어나라!\'를 사용하여 요릭이 무덤을 통한 소환물을 활용하며 접근하는 것을 방어해야 해요. 초반에는 요릭과 거리를 유지하며 원거리에서 피해를 입히는 것에 집중하세요.', lv3: '요릭의 (E)\'애도의 안개\'에 표식이 남으면 안개 망령이 쫓아오니 구체가 날아오는 것을 보고 미리 피하세요. 요릭이 (W)\'망자의 진\'으로 이동을 막으려 하면 벽은 공격을 받으면 파괴되니 병사로 벽을 공격하며 거리를 벌려야 해요. (Q)\'사막의 맹습\'을 적절히 사용하여 요릭이 무덤을 활용하지 못하도록 계속 압박하세요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 (R)\'황제의 진영\'을 사용해 요릭과의 거리를 확보하세요. 안개 마녀와 요릭이 함께 공격하면 위험하니 (E)\'신기루\'로 위치를 빠르게 옮기며 대응해야 해요. 라인을 빠르게 밀어 요릭이 마녀와 함께 압박하는 상황을 줄이도록 관리하세요.', item: '내셔의 이빨과 마법사의 신발을 가세요. 공격 속도와 주문력을 높여 지속적인 피해를 입히고 마법 관통력을 얻기 위해서예요.', spell: '점멸과 점화를 추천해요. 점화로 요릭의 (Q)\'최후의 의식\' 회복을 억제할 수 있어요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\'으로 평타 피해를 높이며 다가오면 (Q)\'사막의 맹습\'으로 거리를 벌리며 견제하세요. 1~2레벨에는 우디르의 (E)\'불길 쇄도\' 기절에 맞지 않도록 주의하며 거리를 충분히 유지하세요. (Q)\'사막의 맹습\'의 둔화 효과를 사용하여 우디르가 쉽게 붙지 못하게 관리해요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막을 얻으면 (Q)\'사막의 맹습\'을 아껴서 딜을 낭비하지 마세요. 우디르의 (E)\'불길 쇄도\' 기절이 빠진 것을 확인한 뒤 (W)\'일어나라!\'와 (Q)\'사막의 맹습\'을 연계하여 딜교환을 해요. (E)\'신기루\'를 사용하여 우디르가 접근할 때 위치를 빠르게 이동하세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'으로 주변에 둔화를 걸며 다가오면 (R)\'황제의 진영\'으로 거리를 벌리세요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 및 방해 효과에 면역이 된 동안에는 (R)\'황제의 진영\' 밀어내기를 노리지 마세요. 그동안은 (E)\'신기루\'로 안전하게 거리를 유지해요.', item: '루덴의 메아리를 첫 코어로 선택하여 (Q)\'사막의 맹습\'의 견제력을 높이세요. 신발은 우디르의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복할 때 점화를 사용하여 회복 효과를 감소시키세요.' },
    '우르곳': { lv1: '우르곳이 (Q)\'부식성 폭약\'으로 둔화를 걸며 다가오니 폭약의 낙하지점을 빠르게 피하며 (W)\'일어나라!\'로 짧게 견제하세요. 첫 웨이브에서는 (Q)\'사막의 맹습\'으로 우르곳의 접근을 늦추며 거리를 유지하는 것이 중요해요. 너무 가까이 붙으면 (P)\'화염의 메아리\' 피해를 입으니 주의하세요.', lv3: '우르곳이 (Q)\'부식성 폭약\'을 맞힌 뒤 (W)\'심판의 원\'으로 강하게 압박하니, 폭약을 맞았다면 즉시 뒤로 빠지세요. (E)\'경멸\' 돌진이 들어올 때 (E)\'신기루\'로 빠르게 위치를 옮겨 기절과 뒤로 던져지는 효과를 피해야 해요. 상대의 (E)\'경멸\'이 빠진 타이밍에 (Q)\'사막의 맹습\'과 평타를 섞어 딜교환을 하세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 상태에서 체력이 낮아지면 제압당해 처형되니, 체력이 낮을 때는 우르곳과 거리를 최대한 벌리세요. 우르곳이 (E)\'경멸\'로 진입해 거리를 좁히면 (R)\'황제의 진영\'으로 밀어내어 접근을 차단하세요. 정글러가 올 때 (Q)\'사막의 맹습\'으로 적의 퇴로를 늦추고 호응하세요.', item: '내셔의 이빨과 판금 장화를 추천해요. 내셔의 이빨로 공격 속도와 주문력을 높여 지속 피해를 주고, 판금 장화로 우르곳의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 운영과 복귀가 중요하며, (E)\'경멸\' 돌진을 피하기 위해 점멸이 필요해요.' },
    '워윅': { lv1: '(W)\'일어나라!\'를 사용해 원거리에서 계속 견제하며 워윅이 다가오지 못하게 하세요. 워윅의 (Q)\'야수의 송곳니\'는 대상 지정 돌진이라 미니언 뒤에 숨어도 무조건 맞으므로 적절한 거리를 유지해야 해요. 1~2레벨에는 워윅의 기본 공격과 (P)\'끝없는 허기\' 회복이 강하니 무리하게 딜교환을 하지 마세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용해 피해 감소를 얻고 공포를 쓰려 한다면 (E)\'신기루\'로 빠르게 거리를 벌리세요. (W)\'피의 사냥\'으로 이동 속도가 빨라진 워윅에게 (Q)\'사막의 맹습\'을 맞춰 둔화를 걸어 접근을 늦춰야 해요. 워윅의 (Q)\'야수의 송곳니\'가 빠진 타이밍에 (W)\'일어나라!\'로 계속해서 피해를 누적하세요.', lv6: '(R)\'무한의 구속\'은 제압 효과라 정화나 점멸로 풀 수 없으니 정글러 개입 시 각별히 주의하세요. 제압당하면 (R)\'황제의 진영\'도 쓸 수 없으니 워윅이 도약하기 전이나 가까이 붙었을 때 미리 밀어내어 거리를 확보하세요. 체력이 낮은 상태에서는 (W)\'피의 사냥\' 때문에 워윅이 매우 빠르게 다가오니 라인을 당겨서 관리하세요.', item: '판금 장화와 모렐로노미콘을 추천해요. 판금 장화로 워윅의 기본 공격 피해를 줄이고 모렐로노미콘으로 (P)\'끝없는 허기\'와 (Q)\'야수의 송곳니\'의 회복량을 깎아야 해요.', spell: '점멸과 점화를 추천해요. 워윅의 강력한 체력 회복을 점화로 억제해야 낮은 체력에서 살아나는 것을 막을 수 있어요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. (W)\'일어나라!\'를 사용해 병사로 계속 견제하고, 이렐리아가 돌진할 수 있는 미니언 위치를 피해 거리를 벌리세요. (Q)\'사막의 맹습\'을 적절히 섞어 둔화시키면 접근을 늦출 수 있어요.', lv3: '(E)\'쌍검협무\'의 재사용 시 날아오는 칼날에 맞으면 기절하고 표식이 생겨 (Q)\'칼날 쇄도\'가 초기화되니, 칼날이 교차하는 지점에서 빠르게 벗어나세요. 이렐리아가 접근할 때 (E)\'신기루\'로 거리를 벌리거나 보호막으로 피해를 흡수하며 대응하세요. (W)\'저항의 춤\'을 충전하는 동안은 피해량이 감소하니 충전이 끝난 뒤에 (Q)\'사막의 맹습\'으로 공격하세요.', lv6: '(R)\'선봉진격검\'에 적중해 표식이 생기면 (Q)\'칼날 쇄도\'로 빠르게 진입하니, 결계 밖으로 빠르게 이동하세요. 이렐리아가 완전히 진입했을 때 (R)\'황제의 진영\'으로 밀어내어 진형을 붕괴시키고 거리를 확보하세요. 라인을 밀고 있을 때는 정글 개입에 취약하니 (E)\'신기루\'를 아껴두고 주변 시야를 확인하세요.', item: '내셔의 이빨을 첫 코어로 선택해 병사의 공격 속도와 주문력을 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 감소시켜 킬각을 잡기 편해요.' },
    '일라오이': { lv1: '일라오이가 (P)\'고대신의 예언자\' 촉수를 소환하기 쉬운 벽 근처는 피하세요. (Q)\'사막의 맹습\'을 활용해 일라오이가 (Q)\'촉수 강타\'를 쓰기 전에 거리를 유지하며 견제해요. 1~2레벨에는 촉수가 없는 라인 중앙에서 미니언을 챙기며 버티세요.', lv3: '일라오이가 (E)\'영혼의 시험\'으로 내 영혼을 분리하면 영혼에서 너무 멀어지지 않게 주의하세요. 영혼이 맞으면 피해 일부가 나에게 들어오니 일라오이가 영혼을 때리는 동안은 거리를 두세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약할 때는 (E)\'신기루\'를 사용해 거리를 벌리며 대응해요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용해 촉수를 소환하면 (R)\'황제의 진영\'으로 적을 밀어내며 촉수 범위에서 벗어나세요. (E)\'영혼의 시험\'이 걸린 상태에서는 영혼에서 너무 멀어지면 숙주가 되니 조심하며 (E)\'신기루\'로 위치를 잡으세요. 일라오이가 궁극기를 쓴 뒤에는 라인을 당겨서 정글러의 도움을 받도록 해요.', item: '리치베인을 첫 코어로 선택해 스킬과 평타를 섞어 강력한 피해를 입히세요. 신발은 마법 관통력을 제공하는 마법사의 신발이 좋아요.', spell: '점멸과 순간이동을 추천해요. 일라오이가 강한 구간에서 라인을 관리하며 운영에 집중하세요.' },
    '자크': { lv1: '1~2레벨에는 (Q)\'사막의 맹습\'을 활용해 자크의 체력을 깎으며 거리를 유지하세요. 자크가 (Q)\'탄성 주먹\'을 사용해 다가오려 할 때 병사를 이용해 일직선 공격을 가하며 압박하세요. 자크가 조각을 모으기 전에 미리 체력 차이를 벌려 두어야 해요.', lv3: '자크가 (E)\'새총 발사\'를 충전하는 동안 착지 지점을 보고 (E)\'신기루\'나 옆으로 이동해 미리 피하세요. 자크가 근접해서 (W)\'불안정 물질\'을 쓰려 할 때 (W)\'일어나라!\'와 (Q)\'사막의 맹습\'을 섞어 딜교환을 하고 빠져야 해요. 자크의 (Q)\'탄성 주먹\'을 피하면서 병사들로 지속적인 피해를 주세요.', lv6: '자크가 (R)\'바운스!\'를 사용하며 진입할 때 (R)\'황제의 진영\'으로 자크를 밀어내어 공격을 차단하세요. 자크가 (P)\'세포 분열\'로 갈라지면 한 조각이라도 살아남을 경우 부활하니 조각이 흩어지게 두지 말고 확실히 처리하세요. 자크의 (E)\'새총 발사\'가 없는 시간을 활용해 라인을 압박하세요.', item: '루덴의 메아리를 첫 코어로 선택해 마나와 주문력을 확보하며 견제력을 높이세요. 신발은 자크의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 가세요.', spell: '점멸과 점화를 추천해요. 점화로 자크가 (P)\'세포 분열\'을 통해 체력을 회복하는 것을 억제하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 가까이 붙지 마세요. (W)\'일어나라!\'로 병사를 소환해 원거리에서 지속적으로 견제하며 거리 조절을 하세요. 자헨이 (P)\'전쟁 단련\' 중첩을 쌓지 못하게 짧은 딜교환만 하세요.', lv3: '(W)\'공포의 귀환\'에 끌려가면 위험하니 자헨의 공격 방향에서 빠르게 벗어나세요. (E)\'찬란한 쇄도\'로 진입하는 타이밍에 (Q)\'사막의 맹습\'을 사용해 적을 둔화시키고 거리를 벌리세요. (E)\'신기루\'의 보호막을 활용해 자헨의 진입을 한 차례 버티며 대응하세요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아와 내려찍을 때 (R)\'황제의 진영\'으로 밀어내어 흐름을 끊으세요. (P)\'전쟁 단련\' 결심이 가득 차면 부활할 수 있으니 체력이 낮아져도 방심하지 말고 확실히 처리하세요. 자헨이 진입하기 전에 (E)\'신기루\'로 위치를 옮겨 한 박자 피하세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 높여 빠르게 병사 공격을 하세요. 신발은 자헨의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하므로 점화의 치유 감소 효과가 매우 중요해요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 접근하기 전에 (Q)\'사막의 맹습\'으로 거리를 두며 견제하세요. (W)\'일어나라!\'를 활용해 잭스의 (P)\'가차없는 맹공\'이 쌓이지 않도록 원거리에서 마법 피해를 입히는 것이 중요해요. 1~2레벨에는 잭스의 진입을 허용하지 않는 것에 집중하세요.', lv3: '(E)\'반격\'을 켠 잭스는 기본 공격을 피하니 켜진 동안은 평타 교환을 멈추고 기절 범위에서 벗어나세요. 잭스가 (Q)\'도약 공격\'으로 들어올 때 (E)\'신기루\'로 보호막을 얻으며 위치를 선점하세요. (E)\'반격\'의 기절은 근처 적을 모두 묶으니 폭발 범위 밖에서 기다리세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용하여 방어력을 높이면 정면 교환을 피하고 거리를 벌리세요. 잭스가 (Q)\'도약 공격\'으로 들어올 때 (R)\'황제의 진영\'으로 밀어내어 접근을 막는 것이 핵심이에요. 궁극기 지속시간이 끝나면 (E)\'신기루\'와 병사들로 다시 압박하며 킬각을 노리세요.', item: '첫 코어 아이템으로 내셔의 이빨을 가서 지속적인 피해를 높이세요. 신발은 잭스의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 잭스의 체력을 깎아 마무리 피해를 입히세요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 쏘며 견제하니 거리 조절을 하며 (W)\'일어나라!\'로 응수하세요. 제이스가 (Q)\'하늘로!\'로 도약해 들어오려 하면 (Q)\'사막의 맹습\'으로 둔화를 걸어 접근을 늦추세요. 무리하게 다가가기보다 병사를 통해 최대한 체력을 보존하며 파밍하세요.', lv3: '제이스가 (E)\'가속 관문\'을 설치하고 (Q)\'전격 폭발\'을 날리면 빠르게 옆으로 움직여 피하세요. (E)\'천둥 강타\'에 밀려나면 딜교환이 끊기니 해머 형태의 제이스에게 가까이 서지 말고 (E)\'신기루\'로 거리를 유지하거나 보호막으로 피해를 흡수하세요. 제이스의 해머 스킬이 빠진 틈을 타 (Q)\'사막의 맹습\'과 병사 공격으로 지속 피해를 입히세요.', lv6: '제이스가 (R)\'머큐리 해머\'로 바꿔 (Q)\'하늘로!\'로 도약해 들어올 때 (R)\'황제의 진영\'으로 밀어내어 진입을 차단하세요. 해머 형태로 변환해 방어력과 마법 저항력이 높아진 상태에서는 무리한 공격을 피하고 라인을 유지하세요. 제이스가 (E)\'천둥 강타\'를 헛쓴 순간이 가장 좋은 기회이니 (Q)\'사막의 맹습\'과 함께 강력하게 몰아붙이세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 확보해 병사 공격력을 높이세요. 신발은 캐논 형태의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 탑 라인에서 빠르게 복귀하고 (R)\'황제의 진영\'과 점멸을 연계해 상대의 진입을 끊으세요.' },
    '초가스': { lv1: '(W)\'일어나라!\'를 사용하여 초가스의 접근을 방해하며 지속적으로 견제하세요. 초가스가 (E)\'날카로운 가시\'로 둔화를 걸며 다가오면 (Q)\'사막의 맹습\'을 사용하여 거리를 유지하며 미니언을 챙기세요.', lv3: '초가스가 (Q)\'파열\'로 공중으로 띄우려 하면 (E)\'신기루\'의 보호막을 활용하거나 옆으로 피해 보세요. (W)\'흉포한 울부짖음\'에 맞으면 스킬 사용이 제한되니 원뿔 범위 밖에서 (Q)\'사막의 맹습\'으로 딜교환을 하세요.', lv6: '(R)\'포식\'은 큰 고정 피해를 입히고 초가스를 성장시키니 체력이 낮을 때 붙지 않도록 주의하세요. 초가스가 다가오면 (R)\'황제의 진영\'으로 밀어내어 거리를 확보하세요.', item: '첫 코어로 내셔의 이빨을 올려 공격 속도와 주문력을 챙기세요. 신발은 초가스의 마법 피해와 침묵 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (W)\'흉포한 울부짖음\'의 침묵을 정화로 빠르게 풀고 대응할 수 있어요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\' 보호막을 활용해 (Q)\'정확성 프로토콜\'로 강화 평타를 치며 압박해요. 1~2레벨에는 (Q)\'사막의 맹습\'을 사용하여 최대한 멀리서 병사로 견제하며 거리를 유지하세요. 카밀의 보호막이 있을 때는 무리하게 맞서지 말고 병사의 사거리를 활용해 피해를 입히세요.', lv3: '카밀의 (W)\'전술적 휩쓸기\' 바깥쪽 절반에 맞으면 이동 속도가 느려지고 카밀이 체력을 회복하니 휩쓸기 동작이 보이면 범위 밖으로 멀리 물러나세요. 카밀이 벽을 이용해 (E)\'갈고리 발사\'로 도약해 기절을 노릴 때 (E)\'신기루\'로 병사에게 이동하며 거리를 벌리세요. 카밀의 (W)\'전술적 휩쓸기\'가 빠진 타이밍에 (Q)\'사막의 맹습\'을 맞히며 딜교환을 시도하세요.', lv6: '카밀이 (R)\'마법공학 최후통첩\'으로 가두면 안에서는 어떤 방법으로도 탈출할 수 없으니 카밀이 도약하기 전에 거리를 벌리세요. 카밀이 가까이 붙으면 (R)\'황제의 진영\'으로 밀어내어 진입 거리를 끊으세요. 라인이 밀릴 때는 정글러의 도움을 받으며 카밀의 (E)\'갈고리 발사\'를 경계하며 라인을 관리하세요.', item: '내셔의 이빨을 첫 코어로 가서 병사 공격력을 높이세요. 신발은 카밀의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 카밀의 (W)\'전술적 휩쓸기\' 체력 회복 효과를 줄여서 대응하세요.' },
    '카사딘': { lv1: '1~2레벨 구간에는 (W)\'일어나라!\'를 활용해 거리 조절을 하며 계속해서 견제하세요. 상대가 (Q)\'무의 구체\'를 사용해 다가오려 하면 (Q)\'사막의 맹습\'으로 둔화시키며 거리를 벌리세요. 상대의 패시브 (P)\'공허석\' 때문에 피해량이 낮으니 무리하지 말고 파밍에 집중하세요.', lv3: '3레벨 이후에는 (E)\'힘의 파동\'이 충전되었을 때 정면으로 다가가지 않도록 주의하세요. 상대의 (E)\'힘의 파동\'이 빠진 타이밍에 (E)\'신기루\'로 진입하여 짧게 딜교환을 하고 빠르게 빠져나오세요. (Q)\'사막의 맹습\'을 먼저 맞춰 둔화를 건 뒤 병사 공격을 넣는 것이 효율적이에요.', lv6: '6레벨 이후 상대가 (R)\'균열 이동\'으로 순식간에 거리를 좁히면 (R)\'황제의 진영\'으로 즉시 밀어내어 진입을 차단하세요. 라인을 밀어두고 정글러를 불러 함께 압박하는 것이 좋으며 무리한 솔로 킬 시도는 피하세요. (E)\'신기루\'의 보호막을 활용해 (Q)\'무의 구체\'의 피해를 상쇄하며 신중하게 거리 조절을 하세요.', item: '내셔의 이빨과 헤르메스의 발걸음을 추천해요. 공격 속도와 주문력을 높여 지속 딜링 능력을 강화하고 마법 저항력과 강인함으로 상대의 군중 제어 효과를 줄여야 해요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 운영이 중요하며 상대의 기동성에 대응해 빠르게 합류하거나 복귀해야 해요.' },
    '카시오페아': { lv1: '(W)\'일어나라!\'를 사용해 모래 병사로 안전하게 파밍하며 견제하세요. 상대의 (Q)\'맹독 폭발\' 사거리 밖에서 최대한 거리를 유지하며 체력 소모를 줄여야 해요.', lv3: '상대가 (W)\'독기의 늪\'을 사용하기 전까지는 (E)\'신기루\'를 아껴두세요. (Q)\'사막의 맹습\'으로 상대의 접근을 둔화시키며 모래 병사로 지속적인 피해를 입히는 것이 중요해요. (E)\'쌍독니\'는 짧은 간격으로 연달아 들어오니 중독된 상태에서는 거리를 유지하세요.', lv6: '(R)\'황제의 진영\'으로 상대의 진입을 막고 적을 밀어내어 일방적인 딜교환 구도를 만드세요. (R)\'석화의 응시\'를 사용할 때 몸을 돌려 기절을 피하고 둔화 상태에서 빠르게 벗어나야 해요. 라인을 당겨 두고 정글러가 왔을 때 (Q)\'사막의 맹습\'으로 둔화를 걸어 킬각을 잡으세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 헤르메스의 발걸음은 마법 저항력과 강인함으로 군중 제어 시간을 줄여주고 내셔의 이빨은 공격 속도와 주문력으로 병사의 공격력을 높여줘요.', spell: '점멸과 순간이동을 추천해요. 점멸은 갑작스러운 위험에서 벗어나거나 공격 기회를 잡을 때 필요하며 순간이동은 탑 라인의 운영과 빠른 복귀를 위해 필수적이에요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'으로 견제하며 (P)\'폭풍의 표식\'을 쌓아 기절을 노려요. (Q)\'천둥의 표창\'은 처음 적중한 대상에게만 피해를 주니 미니언 뒤에 숨어 공격을 피하세요. 표창 사거리가 더 기니 무리하게 견제하기보다 케넨이 평타를 치러 다가올 때 (W)\'일어나라!\'로 병사를 세워 맞받아치세요.', lv3: '케넨이 (E)\'번개 질주\'로 빠르게 접근해 표식을 쌓으려 하면 (Q)\'사막의 맹습\'으로 둔화시켜 거리를 벌리세요. (W)\'전류 방출\'은 주변 적에게 표식을 남기니 케넨 근처에서 오래 머물지 말고 (E)\'신기루\'로 빠르게 위치를 옮겨야 해요. 표식이 많이 쌓였다면 다음 공격에 기절하니 무리한 교환은 피하세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 켜고 진입하면 (R)\'황제의 진영\'으로 밀어내어 기절이 쌓이는 것을 막으세요. (E)\'번개 질주\'와 궁극기 콤보가 빠진 후에는 (Q)\'사막의 맹습\'과 평타로 강하게 압박할 수 있어요. 정글러가 올 때 케넨의 기절 콤보에 묶이지 않도록 거리를 유지하며 라인을 관리하세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 높여 빠르게 병사 공격을 하세요. 신발은 케넨의 마법 피해를 줄이고 기절 지속시간을 낮추는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 인한 기절을 정화로 즉시 풀 수 있어요.' },
    '케일': { lv1: '1~2레벨 구간은 케일의 (P)\'거룩한 승천\'이 아직 발동되지 않아 사거리가 짧은 시기예요. (W)\'일어나라!\'로 병사를 세워 지속적으로 견제하고, 상대가 (Q)\'광휘의 일격\'을 쓰러 다가오면 거리 조절을 하며 피해를 최소화하세요. 초반부터 적극적으로 압박해 상대가 편하게 성장하지 못하게 하세요.', lv3: '(E)\'화염주문검\'의 잃은 체력 비례 피해가 아프니 내 체력이 낮을 때는 무리한 딜교환을 피하세요. 케일이 (W)\'천상의 축복\'으로 회복하며 빠져나갈 때 (Q)\'사막의 맹습\'으로 둔화를 걸어 추격하거나 견제하세요. (E)\'신기루\'의 보호막을 활용해 (Q)\'광휘의 일격\' 피해를 흡수하며 진입했다가 빠르게 빠지는 식으로 운영하세요.', lv6: '(R)\'신성한 심판\'은 대상을 무적으로 만드니 궁극기가 켜진 동안에는 공격을 멈추고 기다리세요. 무적이 끝나는 타이밍에 (E)\'신기루\'와 병사들로 압박하며 딜각을 잡으세요. 케일의 사거리가 점점 늘어나니 라인 관리를 통해 정글러가 개입하기 좋은 구도를 만들어 함께 처리하세요.', item: '내셔의 이빨과 헤르메스의 발걸음을 추천해요. 내셔의 이빨은 공격 속도와 주문력을 높여 평타 기반 딜교환을 돕고, 헤르메스의 발걸음은 케일의 마법 피해를 줄이고 둔화 지속시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 케일이 (W)\'천상의 축복\'으로 회복하는 양을 줄이고 초반에 빠르게 처치해 성장을 억제하세요.' },
    '코그모': { lv1: '1~2레벨에는 (Q)\'부식성 침\'의 긴 사거리로 인해 압박을 받을 수 있어요. (W)\'일어나라!\'와 (Q)\'사막의 맹습\'을 활용해 미니언 뒤에서 병사로 견제하며 거리를 유지하세요. 상대의 방어력을 낮추는 공격을 최대한 피하며 라인을 받아내야 해요.', lv3: '(W)\'생체마법 폭격\'이 활성화된 동안에는 사거리가 매우 길어지니 주의하세요. 상대의 (W)\'생체마법 폭격\'이 끝난 것을 확인하고 (E)\'신기루\'로 진입해 짧은 딜교환을 시도해요. (E)\'공허의 분비물\'이 남긴 둔화 장판을 밟지 않도록 무빙에 신경 써야 해요.', lv6: '(R)\'살아있는 곡사포\'의 사거리가 매우 길기 때문에 멀리서 일방적으로 맞지 않도록 조심하세요. 정글러와 함께 진입할 때는 (R)\'황제의 진영\'의 병사 벽으로 퇴로를 막고 킬각을 보세요. 상대 체력이 낮을 때 들어오는 폭발적인 피해를 피하는 것이 중요해요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 마법 저항력을 챙겨 피해를 줄이고 이케시아의 이빨 효과를 통해 병사의 공격력을 높여 효율적인 전투를 수행해요.', spell: '점멸과 탈진을 추천해요. 점멸을 활용해 위치를 잡고 탈진으로 상대의 피해량을 줄여야 해요.' },
    '코르키': { lv1: '코르키가 (Q)\'인광탄\'을 던질 때 좌우로 움직여 범위를 피하며 피해를 줄이세요. (W)\'일어나라!\'를 사용해 적절한 거리를 유지하며 기본 공격으로 견제해요. (Q)\'인광탄\'에 맞은 지역과 챔피언이 드러나니 수풀에서의 합류를 조심하며 체력 관리에 집중하세요.', lv3: '코르키가 (W)\'발키리\'로 진입할 때 (E)\'신기루\'의 보호막으로 피해를 흡수하며 빠르게 거리를 벌리세요. (Q)\'사막의 맹습\'을 사용하여 상대의 이동 속도를 늦추고 (E)\'개틀링 건\'의 사거리 밖으로 벗어나요. 상대의 이동기가 빠진 틈을 타 (W)\'일어나라!\'로 지속적인 마법 피해를 입히세요.', lv6: '코르키의 (R)\'미사일 폭격\' 세 번째 미사일은 피해가 크므로 각별히 주의하세요. 상대가 (W)\'발키리\'로 진입하는 순간 (R)\'황제의 진영\'을 사용해 뒤로 밀어내며 진입을 차단해요. (Q)\'사막의 맹습\'으로 적을 둔화시키고 정글러가 왔을 때 함께 공격하면 킬을 잡기 편해요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화는 코르키의 기본 공격 피해를 줄여주며 내셔의 이빨은 공격 속도와 주문력을 높여 (W)\'일어나라!\'의 공격 효율을 올려줘요.', spell: '점멸과 순간이동을 추천해요. 갑작스러운 거리 조절로 생존하고 빠른 합류와 복귀가 필요하기 때문이에요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식이 붙은 대상에게 첫 평타가 강력하니 거리를 조절하며 받아내야 해요. (Q)\'실명 공격\'은 처음 적중한 적에게 표식과 시야 감소를 거니 미니언을 사이에 두고 서세요. (Q)\'사막의 맹습\'으로 멀리서 퀸의 체력을 깎으며 첫 웨이브를 안전하게 가져가세요.', lv3: '퀸의 (E)\'공중제비\'를 먼저 유도한 뒤에 딜교환을 시도하는 것이 좋아요. 퀸이 (E)\'공중제비\' 사용 후 뒤로 물러나면 (W)\'일어나라!\'를 활용해 병사로 압박하세요. (Q)\'실명 공격\'을 맞지 않도록 주의하며 딜교환을 진행하세요.', lv6: '퀸이 (R)\'후방 지원\'으로 빠르게 다가와 (E)\'공중제비\'를 쓰려 하면 (Q)\'사막의 맹습\'으로 둔화를 걸고 병사로 맞받아치세요. 정글러가 왔을 때는 (R)\'황제의 진영\'으로 퀸을 아군 쪽으로 밀어내 킬각을 만드세요. 퀸이 로밍을 가면 라인을 빠르게 밀어 포탑 압박을 유지하세요.', item: '첫 코어로 루덴의 메아리를 가서 스킬 피해를 극대화하세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 탈진으로 퀸을 둔화시키고 입히는 피해량을 줄여 생존하기에 좋아요.' },
    '크산테': { lv1: '(W)\'일어나라!\'를 사용하여 모래 병사로 지속적으로 견제하며 거리를 유지하세요. (Q)\'엔토포 타격\'이 두 번 적중해 중첩이 쌓이면 다음 사용은 기절시키며 끌어당기는 충격파가 되니 그때는 사거리 밖으로 물러나야 해요. 1~2레벨에는 상대의 진입 수단이 적으니 최대한 체력을 깎아 두세요.', lv3: '(W)\'길을 여는 자\'는 저지 불가 상태로 돌진하며 적을 뒤로 밀어내고 기절시키니, 충전 동작이 보이면 즉시 경로에서 벗어나세요. (E)\'발놀림\'으로 빠르게 접근하는 크산테에게 (E)\'신기루\'를 사용해 거리를 벌린 뒤 (Q)\'사막의 맹습\'으로 둔화를 걸어 일방적인 딜교환을 하세요. 상대의 주요 돌진기가 빠진 틈을 타 모래 병사로 피해를 누적시키세요.', lv6: '(R)\'총공세\'를 사용하면 크산테가 적을 밀어내고 벽을 뚫을 수 있으며, 이후 방어력이 낮아지는 대신 공격 속도와 피해 흡혈이 올라가요. 벽 근처에 서 있으면 한 번에 멀리 밀려나 위험하니 라인 중앙에서 유지하세요. 크산테가 총공세 상태로 진입할 때 (R)\'황제의 진영\'으로 밀어내어 접근을 차단하고 거리를 벌리세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 상대에게 지속 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 크산테는 체력이 많아 처치가 어려우니 순간이동으로 라인 손해를 최소화하세요.' },
    '클레드': { lv1: '1~2레벨 구간에는 클레드가 (Q)\'덫날리기\'로 붙잡고 끌어당기지 못하도록 거리 조절을 잘해야 해요. (Q)\'사막의 맹습\'으로 멀리서 모래 병사를 보내 클레드의 체력을 미리 깎으며 압박하세요. 클레드의 (Q)\'덫날리기\'가 빠진 타이밍에 (W)\'일어나라!\'를 활용해 일직선상으로 견제하면 좋아요.', lv3: '클레드가 (E)\'이랴!\'를 사용하여 돌진해 올 때는 (E)\'신기루\'로 거리를 벌리거나 위치를 선점하세요. 클레드가 (W)\'버럭버럭\'을 켜고 빠르게 공격하려 하면 근접해서 맞대응하지 말고 (W)\'일어나라!\'를 사용해 거리를 유지해야 해요. 클레드의 (Q)\'덫날리기\'가 빗나갔을 때 모래 병사들을 활용해 딜교환을 시도하세요.', lv6: '클레드가 (R)\'돌겨어어억!!!\'을 사용해 돌진해오면 (R)\'황제의 진영\'으로 경로를 막아 클레드를 밀어내세요. 클레드가 스칼에서 내려 용기를 채우려 할 때 (E)\'신기루\'와 병사들을 사용해 빠르게 몰아붙여야 해요. 라인을 당겨서 받아먹으며 정글러를 호출해 클레드가 무리하게 진입하지 못하게 만드세요.', item: '내셔의 이빨을 첫 코어 아이템으로 선택해 모래 병사와 함께 지속적인 피해를 입히세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 클레드가 스칼에서 내려 체력이 낮아졌을 때 점화로 빠르게 처치할 수 있어요.' },
    '탐켄치': { lv1: '1~2레벨 구간에는 탐 켄치가 (Q)\'혀 채찍\'을 사용하면 미니언 뒤에 서서 피해를 피하세요. (Q)\'혀 채찍\'은 챔피언에게 적중해야 체력을 회복하므로 미니언을 사이에 두고 (Q)\'사막의 맹습\'으로 견제하는 것이 좋아요. (P)\'절대 미각\' 중첩이 쌓이지 않게 짧게 교환하며 거리를 유지하세요.', lv3: '탐 켄치가 (W)\'심연 잠수\'로 들어와 공중으로 띄우려 하면 (E)\'신기루\'를 사용하여 위치를 옮기세요. (E)\'두꺼운 피부\'를 사용해 보호막이 생겼을 때는 피해를 입히기보다 보호막이 사라질 때까지 기다리는 것이 좋아요. (P)\'절대 미각\' 중첩이 세 번 쌓여 기절하기 전에 짧게 교환하고 거리를 벌리세요.', lv6: '(P)\'절대 미각\' 중첩이 쌓인 상태에서 붙으면 (R)\'집어삼키기\'에 먹힐 수 있으니 조심하세요. 탐 켄치가 다가오면 (R)\'황제의 진영\'을 사용하여 밀어내고 거리를 확보하세요. 라인을 빠르게 밀어 탐 켄치가 (E)\'두꺼운 피부\'로 체력을 회복할 틈을 주지 않도록 압박하는 것이 중요해요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 탐 켄치에게 지속적인 마법 피해를 입히세요. 신발은 마법 관통력이 붙은 마법사의 신발이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\' 회복 효과를 줄여 킬각을 잡으세요.' },
    '트런들': { lv1: '(W)\'일어나라!\'로 모래 병사를 소환해 원거리에서 계속 견제하세요. 트런들이 (Q)\'깨물기\'를 쓰러 접근하면 뒤로 물러나며 거리를 유지해야 해요. 첫 웨이브부터 거리 조절을 하며 (Q)\'깨물기\'의 둔화와 공격력 흡수를 피하세요.', lv3: '트런들이 (E)\'얼음 기둥\'을 세우면 이동 경로가 막히고 둔화되니 기둥의 위치를 잘 확인하세요. (W)\'얼음 왕국\' 위에서는 트런들의 공격 속도가 빨라지니 영역 밖에서 (Q)\'사막의 맹습\'으로 둔화를 걸며 딜교환하세요. (E)\'신기루\'의 보호막을 활용해 (Q)\'깨물기\' 피해를 상쇄하고 빠르게 빠져나가세요.', lv6: '트런들이 (R)\'진압\'을 쓰면 체력과 방어력, 마법 저항력을 훔쳐가므로 즉시 (R)\'황제의 진영\'으로 밀어내어 거리를 벌리세요. (R)\'진압\'이 걸린 동안은 내 방어력과 마법 저항력이 낮아지니 무리하게 교환하지 말고 라인을 당겨 정글 개입을 기다리세요. (E)\'얼음 기둥\'으로 도망길을 막는 갱킹이 위험하니 벽 근처에서는 항상 주의하세요.', item: '내셔의 이빨을 가서 주문력과 공격 속도를 높여 병사 딜을 올리세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트런들이 (P)\'헌납\'과 (W)\'얼음 왕국\'으로 회복하는 양이 많으니 점화의 치유 감소 효과로 맞대응하세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'로 치명타 확률을 높이며 공격하니 거리를 유지하며 (Q)\'사막의 맹습\'으로 견제하세요. 초반에는 트린다미어의 평타 사거리에 들어가지 않도록 주의하며 웨이브를 관리하세요. (W)\'일어나라!\'로 모래 병사를 소환해 거리 조절에 집중하는 것이 중요해요.', lv3: '트린다미어가 (E)\'회전 베기\'로 접근하면 (E)\'신기루\'를 사용하여 거리를 벌리거나 위치를 옮기세요. (W)\'조롱의 외침\'은 공격력을 낮추고 등을 돌린 챔피언을 둔화시키니 주의하며, (Q)\'사막의 맹습\'의 둔화 효과를 활용해 트린다미어가 붙지 못하게 하세요. 트린다미어의 (Q)\'피의 갈망\' 사용을 유도하거나 그 전에 짧게 딜교환을 하고 빠지세요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 사용하면 일정 시간 동안 죽지 않으니 딜을 쏟기보다 (R)\'황제의 진영\'으로 밀어내며 시간을 버세요. 궁극기 지속 시간이 끝난 뒤 트린다미어의 체력이 낮을 때 (Q)\'사막의 맹습\'과 (W)\'일어나라!\'로 몰아붙여 킬을 노리세요. 라인을 밀어두고 정글러를 불러 트린다미어가 (Q)\'피의 갈망\'으로 회복하기 전에 압박하는 것이 좋아요.', item: '첫 코어로 내셔의 이빨을 선택하여 모래 병사의 공격 속도를 높이세요. 신발은 트린다미어의 기본 공격 피해를 줄여주는 판금 장화를 신으세요.', spell: '점멸과 점화를 추천해요. 점화는 트린다미어가 (Q)\'피의 갈망\'을 사용하여 체력을 회복하는 것을 억제할 수 있어요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'를 통해 지속적인 마법 피해를 입히니 평타를 맞지 않게 거리를 조절하세요. 수풀 근처에서는 (P)\'유격 전투\'로 투명해진 티모를 주의하며 (Q)\'사막의 맹습\'으로 먼저 견제해요. 초반에는 무리한 접근보다는 병사를 활용해 거리를 유지하며 대응하세요.', lv3: '티모의 (Q)\'실명 다트\'에 맞으면 실명 상태가 되니 실명이 빠진 직후에 (E)\'신기루\'로 진입하거나 (Q)\'사막의 맹습\'을 활용하세요. 티모가 (W)\'신속한 이동\'을 사용해 거리를 벌린다면 (Q)\'사막의 맹습\'의 둔화를 이용해 따라붙으며 딜교환을 시도해요. (W)\'일어나라!\'로 소환한 병사를 통해 안전한 거리에서 피해를 입히는 것이 좋아요.', lv6: '티모가 설치한 (R)\'유독성 함정\'은 밟으면 둔화와 피해를 주니 버섯이 깔린 길목을 피해서 이동하세요. (R)\'황제의 진영\'으로 티모를 밀어내어 원하는 위치로 유도하거나 아군 쪽으로 밀어낼 수 있어요. 티모가 라인을 비우면 버섯을 깔러 간 것일 수 있으니 라인 관리에 신경 쓰며 정글의 도움을 기다리세요.', item: '내셔의 이빨을 첫 코어로 선택하여 주문력과 공격 속도를 높이세요. 신발은 티모의 마법 피해를 견디기 위해 헤르메스의 발걸음을 신어요.', spell: '점멸과 점화를 추천해요. 티모는 체력이 낮아지면 도망치기 쉬우니 점화로 빠르게 처치하세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 던지거나 찔러서 1~2레벨 구간에 강하게 압박해요. (Q)\'사막의 맹습\'을 활용해 최대한 거리를 유지하며 병사로 견제하고 파밍에 집중하세요. 판테온이 (P)\'필멸자의 의지\'를 쌓아 강화된 스킬을 쓰려 하면 거리를 더 벌려야 해요.', lv3: '판테온이 (W)\'방호의 도약\'을 사용해 돌진하면 대상 지정 스킬이라 (E)\'신기루\'로 피하기 어려우니 주의하세요. 판테온이 (E)\'방패 돌격\'을 켜고 정면으로 공격할 때는 피해를 입지 않으니 (W)\'일어나라!\'로 옆이나 뒤를 노려 딜교환하세요. 판테온의 (W)\'방호의 도약\'이 빠진 타이밍에 (Q)\'사막의 맹습\'을 맞춰 거리 조절을 하는 것이 좋아요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 공중에서 떨어지면 (R)\'황제의 진영\'으로 밀어내어 진입을 막으세요. 판테온이 (R)\'거대 유성\'으로 착지하며 둔화를 걸 때 (E)\'신기루\'로 위치를 옮기며 대응하는 것이 중요해요. 판테온의 궁극기 사용은 다른 라인 교전 신호일 수 있으니 미니맵을 확인하고 라인 관리에 신경 쓰세요.', item: '첫 코어 아이템으로 내셔의 이빨을 구매해 공격 속도와 주문력을 챙기세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'방호의 도약\'에 걸리는 기절은 정화로 풀 수 있어요.' },
    '피들스틱': { lv1: '(W)\'일어나라!\'를 사용하여 원거리에서 계속 견제하세요. 상대가 (E)\'수확\'을 사용해 다가오면 거리를 유지하며 피해를 최소화하세요. 시야가 없는 곳에서 (Q)\'공포\'에 걸리지 않도록 주의해요.', lv3: '상대의 (E)\'수확\' 침묵이 빠진 것을 확인한 뒤 딜교환을 시도하세요. (W)\'풍작\'은 집중하는 동안 피해를 주니 범위에 들어가지 않도록 거리를 벌리세요. 위험한 상황에서는 (E)\'신기루\'의 보호막을 활용해 빠르게 이탈하세요.', lv6: '상대가 (R)\'까마귀 폭풍\'으로 진입하는 순간 (R)\'황제의 진영\'을 사용해 밀어내며 피해 범위를 벗어나세요. 보이지 않는 곳에서 날아오는 (Q)\'공포\'를 조심하며 신중하게 라인을 관리해요. 정글러와 함께 싸울 때는 (Q)\'사막의 맹습\'으로 둔화를 걸어 피들스틱의 도주를 늦추세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 가세요. 강인함으로 (Q)\'공포\'의 지속시간을 줄이고 공격 속도로 빠르게 공격해요.', spell: '점멸과 순간이동을 추천해요. 탑 라인 특성상 빠른 합류와 복귀가 필요해요.' },
    '피오라': { lv1: '1~2레벨에는 (W)\'일어나라!\'를 통해 최대한 멀리서 공격하며 피오라가 접근하지 못하게 하세요. 피오라가 (Q)\'찌르기\'로 빠르게 진입할 수 있으니 (P)\'치명적인 검무\'로 드러나는 급소의 방향을 계속 피해 움직이세요. 적절한 거리에서 병사로 견제하며 체력을 깎아두는 것이 중요해요.', lv3: '피오라가 (W)\'응수\'를 사용하면 모든 공격과 이동 불가 효과를 막아내니, 효과가 끝날 때까지 (Q)\'사막의 맹습\'을 아끼세요. (W)\'응수\'가 빠진 것을 확인한 뒤 (E)\'신기루\'로 빠르게 위치를 옮기며 병사로 공격하세요. (E)\'대가의 검술\'을 사용한 피오라의 강화 평타 거리에서는 계속 물러나며 거리를 유지하세요.', lv6: '피오라가 (R)\'대결투\'를 사용하여 급소를 모두 드러내면 (R)\'황제의 진영\'으로 밀어내어 접근을 차단하세요. 밀려난 피오라가 다시 (Q)\'찌르기\'로 들어올 때 병사로 지속적인 피해를 입히세요. 라인을 밀어 넣고 정글러를 불러 함께 공격하여 피오라가 (P)\'치명적인 검무\'로 회복할 틈을 주지 마세요.', item: '내셔의 이빨을 첫 코어로 선택해 주문력과 공격 속도를 높여 병사 공격력을 강화하세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'나 (R)\'대결투\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 방해하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 장악하며 포탑 주변에서 이동 속도가 올라가요. 1~2레벨에는 포탑 사거리 안으로 들어가지 말고 (Q)\'사막의 맹습\'으로 미니언과 함께 멀리서 견제하세요. 포탑 근처에서 싸우기보다 포탑의 공격 범위를 벗어난 곳에서 미니언을 챙기는 게 좋아요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'에 직격당하면 기절하니 수류탄이 떨어지는 위치를 확인해 피하세요. (W)\'마법공학 초소형 로켓\'은 마우스 커서 위치로 모이니 로켓들이 모여드는 경로에 서 있지 않도록 주의하세요. 상대의 수류탄이 빠진 타이밍에 (W)\'일어나라!\'를 활용해 병사로 딜교환을 시도하세요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰면 피해가 매우 크니 조심하세요. 하이머딩거가 포탑 쪽으로 접근하지 못하도록 (R)\'황제의 진영\'의 병사 벽으로 길을 막으면 킬각을 잡기 편해요. 포탑이 정리된 타이밍에 맞춰 압박하거나 정글러를 불러 하이머딩거를 노리세요.', item: '루덴의 메아리를 첫 코어로 가서 스킬 견제력을 높이세요. 신발은 하이머딩거의 마법 피해와 (E)\'CH-2 전자폭풍 수류탄\' 기절 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진으로 하이머딩거의 폭발적인 마법 피해를 감소시키며 싸울 수 있어요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_azir);
if (typeof module !== 'undefined') module.exports = top_azir;
